class Solution:
    def wordPattern(self, pattern: str, s: str) -> bool:
        s = s.strip().split()
        if len(pattern) != len(s):
            return False
        c_dict = {}
        w_dict = {}
        for p, word in zip(pattern.lower(), s):
            if p in c_dict and c_dict[p] != word:
                return False
            if word in w_dict and w_dict[word] != p:
                return False 
            c_dict[p] = word
            w_dict[word] = p
        return True

class Solution:
    def moveZeroes(self, nums: List[int]) -> None:
        left = 0

        for right in range(len(nums)):
            if nums[right] != 0:
                nums[right], nums[left] = nums[left], nums[right]
                left += 1
        
        return nums

