class Solution:
    def sumOfLeftLeaves(self, root: Optional[TreeNode]) -> int:
        def helper(root, is_left):
            if root is None:
                return 0
            if root.left is None and root.right is None:
                return root.val if is_left == True else 0
            return helper(root.left, True) + helper(root.right, False)
        return helper(root.left, True) + helper(root.right, False)

class Solution:
    def readBinaryWatch(self, num: int) -> list[str]:
        times = []

        for h in range(12):
            for m in range(60):
                hOnes = bin(h).count('1')
                mOnes = bin(m).count('1')

                if hOnes + mOnes == num:
                    times.append(f"{h}:{m:02d}")

        return times

class Solution:
    def isSubsequence(self, s: str, t: str) -> bool:
        sp = tp = 0

        while sp < len(s) and tp < len(t):
            if s[sp] == t[tp]:
                sp += 1
            tp += 1
        
        return sp == len(s)

class Solution:
    def findTheDifference(self, s: str, t: str) -> str:
        # Initialize a dictionary to store character counts
        count = {}

        # Count characters in string t
        for c in t:
            count[c] = count.get(c, 0) + 1

        # Subtract counts for characters in string s
        for c in s:
            count[c] -= 1
            if count[c] == 0:
                del count[c]

        # The remaining character in the dictionary is the difference
        return list(count.keys())[0]

class Solution:
    def firstUniqChar(self, s: str) -> int:
        char_count = {}
        
        # Count the frequency of each character
        for char in s:
            char_count[char] = char_count.get(char, 0) + 1
        
        # Find the index of the first unique character
        for index, char in enumerate(s):
            if char_count[char] == 1:
                return index
        
        return -1  # Return -1 if no unique character is found

class Solution:
    def canConstruct(self, ransomNote: str, magazine: str) -> bool:
        maga_hash = {}

        for c in magazine:
            maga_hash[c] = 1 + maga_hash.get(c, 0)

        for c in ransomNote:
            if c not in maga_hash or maga_hash[c] <= 0:
                return False
            maga_hash[c] -= 1
        
        return True

class Solution(GuessGame):
    def guessNumber(self, n: int) -> int:
        first, last = 1, n
        while first <= last:
            mid = first + (last - first) // 2
            res = self.guess(mid)
            if res == 0:
                return mid
            elif res == -1:
                last = mid - 1
            else:
                first = mid + 1
        return -1

