class Solution:
    def longestPalindrome(self, s: str) -> int:
        odd_count = 0
        d = {}
        for ch in s:
            if ch in d:
                d[ch] += 1
            else:
                d[ch] = 1
            if d[ch] % 2 == 1:
                odd_count += 1
            else:
                odd_count -= 1
        if odd_count > 1:
            return len(s) - odd_count + 1
        return len(s)

class Solution:
    def licenseKeyFormatting(self, s: str, k: int) -> str:
        chars = []
        for ch in s:
            if ch == '-':
                continue
            chars.append(ch.upper())

        result = []
        count = 0
        for ch in reversed(chars): #reverse chars
            if count == k:
                result.append('-')
                count = 0
            result.append(ch)
            count += 1
        return ''.join(reversed(result))

