class Solution:
    def transformArray(self, nums: List[int]) -> List[int]:
        even, odd = 0, 0
        for i in nums:
            if i % 2 == 0:
                even += 1
            else:
                odd += 1
        result = [0] * even + [1] * odd
        return result

