class Solution:
    def isWinner(self, player_1_scores, player_2_scores):
        len_player_1_scores = len(player_1_scores)
        len_player_2_scores = len(player_2_scores)
        sum_player_1_scores = 0
        sum_player_2_scores = 0
        i = 0
        while (i < len_player_1_scores):
            sum_player_1_scores += 2 * player_1_scores[i] if (i >= 1 and player_1_scores[i-1] == 10) or (i >= 2 and player_1_scores[i-2] == 10) else player_1_scores[i]
            sum_player_2_scores += 2 * player_2_scores[i] if (i >= 1 and player_2_scores[i-1] == 10) or (i >= 2 and player_2_scores[i-2] == 10) else player_2_scores[i]
            i += 1

        if (sum_player_1_scores == sum_player_2_scores):
            return 0
        elif (sum_player_1_scores > sum_player_2_scores):
            return 1
        elif (sum_player_1_scores < sum_player_2_scores):
            return 2

class Solution:
    def minimumAverage(self, nums: list[int]) -> float:
        nums.sort()
        n = len(nums)
        minAvg = float('inf')
        for i in range(n // 2):
            minAvg = min(minAvg, (nums[i] + nums[n - 1 - i]) / 2)
        return minAvg

class Solution:
    def distinctAverages(self, nums: list[int]) -> int:
        avg = set()
        while nums:
            a = max(nums)
            b = min(nums)
            nums.remove(a)
            nums.remove(b)
            avg.add((a+b)/2)
        return len(avg)

class Solution:
    def countValidSelections(self, nums: List[int]) -> int:
        n, res = len(nums), 0
        left, right = [0 for _ in range(n)], [0 for _ in range(n)]
        for i in range(1, n):
            left[i] = left[i - 1] + nums[i - 1]
            right[-i - 1] = right[-i] + nums[-i]
        for i, num in enumerate(nums):
            if num != 0: continue
            if left[i] == right[i]: res += 2
            if abs(left[i] - right[i]) == 1: res += 1
        return res

class Solution:
    def maximumLengthSubstring(self, s: str) -> int:

        lftLst = iter(s)
        ans, left = 0, next(lftLst)
        ctr = defaultdict(int)

        for rght in s: 

            ctr[rght]+= 1

            while ctr[rght] == 3: 
                ctr[left]-= 1
                left = next(lftLst)

            ans = max(ans, sum(ctr.values()))

        return ans

