class Solution:
    def isBoomerang(self, points: List[List[int]]) -> bool:
        # Extract the points
        (x1, y1), (x2, y2), (x3, y3) = points
        
        # Check if all points are distinct
        if (x1 == x2 and y1 == y2) or (x1 == x3 and y1 == y3) or (x2 == x3 and y2 == y3):
            return False
        
        # Calculate the area (determinant) to check collinearity
        area = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)
        
        return area != 0

class Solution:
    def findKOr(self, nums: List[int], k: int) -> int:
        
        dp = [0]*31
        
        for num in nums:
            i = 0    
            while num > 0:
                if num & 1 == 1:
                    dp[i] += 1
                i += 1
                num = num >> 1

        ans = 0
        for i,count in enumerate(dp):
            if count >= k:
                ans += 2**i
                
        return ans

class Solution:
    def isCousins(self, root: TreeNode, x: int, y: int) -> bool:
        def findLevelAndParent(node, parent, val, level):
            if not node:
                return None
            if node.val == val:
                return (level, parent)
            return findLevelAndParent(node.left, node, val, level + 1) or \
                   findLevelAndParent(node.right, node, val, level + 1)

        x_level, x_parent = findLevelAndParent(root, None, x, 0)
        y_level, y_parent = findLevelAndParent(root, None, y, 0)
        return x_level == y_level and x_parent != y_parent

class Solution:
    def getMinDistance(self, nums, target, start):
        len_nums = len(nums)

        try:
            target_index_1 = nums.index(target, start)
            a = abs(target_index_1 - start)
        except:
            target_index_1 = None

        try:
            target_index_2 = nums[::-1].index(target, len_nums-start-1)
            b = abs(target_index_2 - (len_nums-start-1))
        except:
            target_index_2 = None
            

        if (target_index_2 is None):
            return a
        elif (target_index_1 is None):
            return b
        else:
            return min(a, b)

class Solution:
    def longestAlternatingSubarray(self, v, k):
        ans = 0
        for i in range(len(v)):
            ct = 0
            if (v[i] % 2 == 0) and (v[i] <= k):
                ct = 1
                for j in range(i + 1, len(v)):
                    if (v[j] % 2 == v[j - 1] % 2) or v[j] > k:
                        break
                    ct += 1
            ans = max(ans, ct)
        return ans

class Solution:
    def sortByBits(self, arr: List[int]) -> List[int]:
        # Define a custom comparison key function for sorting
        def custom_sort_key(num):
            # Calculate the number of set bits (1s) in the binary representation of num
            bit_count = bin(num).count('1')
            return (bit_count, num)

        # Sort the input list using the custom comparison key function
        arr.sort(key=custom_sort_key)

        # Return the sorted list
        return arr

