class Solution:
    def convertTime(self, current: str, correct: str) -> int:
        hcurr, mcurr = int(current[:2]), int(current[3:])
        hcorr, mcorr = int(correct[:2]), int(correct[3:])
        curr = 60*hcurr + mcurr
        corr = 60*hcorr + mcorr
        delta = corr - curr
        ops = 0
        for op in [60,15,5,1]:
            if delta >= op:
                ops += delta//op
                delta -= op*(delta//op)
        return ops

