class Solution:
    def findJudge(self, n: int, trust: List[List[int]]) -> int:
        if len(trust) == 0 and n == 1: return 1
        count = [0] * (n + 1)
        for i, j in trust:
            count[i] -= 1
            count[j] += 1
        for p, c in enumerate(count):
            if c == n - 1: return p
        return -1

from collections import defaultdict, Counter
class Solution:
    def findShortestSubArray(self, nums: List[int]) -> int:
        count = Counter(nums)
        left = {}
        right = {}
        
        for i, num in enumerate(nums):
            if num not in left:
                left[num] = i
            right[num] = i

        degree = max(count.values())
        min_len = len(nums)

        for num in count:
            if count[num] == degree:
                min_len = min(min_len, right[num] - left[num] + 1)

        return min_len

