class Solution:
    def generate(self, numRows: int) -> List[List[int]]:
        if numRows == 0:
            return []
        if numRows == 1:
            return [[1]]
        
        prevRows = self.generate(numRows - 1)
        newRow = [1] * numRows
        
        for i in range(1, numRows - 1):
            newRow[i] = prevRows[-1][i - 1] + prevRows[-1][i]
        
        prevRows.append(newRow)
        return prevRows

class Solution:
    def hasPathSum(self, root: Optional[TreeNode], targetSum: int) -> bool:
        if not root:
            return False
        
        if not root.left and not root.right:
            return targetSum - root.val == 0
        
        targetSum -= root.val
        
        return self.hasPathSum(root.left, targetSum) or self.hasPathSum(root.right, targetSum)

from collections import deque
class Solution:
    def minDepth(self, root: TreeNode) -> int:
        if not root:
            return 0  # If the tree is empty, return depth 0
        
        queue = deque([(root, 1)])  # Initialize the queue with the root node and depth 1
        
        while queue:
            node, depth = queue.popleft()
            
            # If it's a leaf node, return the current depth
            if not node.left and not node.right:
                return depth
            
            # Add left and right children to the queue, if they exist
            if node.left:
                queue.append((node.left, depth + 1))
            if node.right:
                queue.append((node.right, depth + 1))

class Solution:
    def isBalanced(self, root: Optional[TreeNode]) -> bool:
        
        def dfs(root):
            if not root:
                return [True, 0]
            
            left_balanced, left_height = dfs(root.left)
            right_balanced, right_height = dfs(root.right)
            
            is_balanced = left_balanced and right_balanced and abs(left_height - right_height) <= 1
            
            return [is_balanced, 1 + max(left_height, right_height)]
        
        return dfs(root)[0]

