class Solution:
    def lengthOfLongestSubsequence(self, nums, sum):
        n = len(nums)
        dp = [[-1] * (sum + 1) for _ in range(n + 1)]
        
        for i in range(n + 1):
            dp[i][0] = 0
        
        for i in range(1, n + 1):
            for j in range(1, sum + 1):
                dp[i][j] = dp[i - 1][j]
                if j >= nums[i - 1] and dp[i - 1][j - nums[i - 1]] != -1:
                    dp[i][j] = max(1 + dp[i - 1][j - nums[i - 1]], dp[i][j])
        
        return dp[n][sum]

class Solution:
    def stoneGameVI(self, alice: List[int], bob: List[int]) -> int:
        t=list(zip(alice,bob))
        t=sorted(t,key=lambda x: sum(x),reverse=True)
        al=sum([i[0] for i in t[::2]])
        bb=sum([i[1] for i in t[1::2]])
        if al>bb:
            return 1
        elif al<bb:
            return -1
        return 0

class Solution:
    def __init__(self):
        self.dp = None

    def solve(self, c, l, r, i):
        n = len(c)
        if i >= n // 2:
            return 0

        if self.dp[i][l][r] != -1:
            return self.dp[i][l][r]

        left_choices = [j for j in range(3) if j != l]
        right_choices = [j for j in range(3) if j != r]

        ans = float('inf')

        for h in left_choices:
            for j in right_choices:
                if h == j:
                    continue
                cl = c[i][h]
                cr = c[n - i - 1][j]
                ans = min(ans, cl + cr + self.solve(c, h, j, i + 1))

        self.dp[i][l][r] = ans
        return ans

    def minCost(self, n, c):
        self.dp = [[[-1] * 4 for _ in range(4)] for _ in range(n // 2 + 1)]
        return self.solve(c, 3, 3, 0)

class Solution:
    def numSquares(self, n: int) -> int:
        dp = [float('inf')] * (n + 1)
        dp[0] = 0
        for i in range(1, n + 1):
            min_val = float('inf')
            j = 1
            while j * j <= i:
                min_val = min(min_val, dp[i - j * j] + 1)
                j += 1
            dp[i] = min_val
        return dp[n]

class Solution:
    def matrixScore(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        res = (1 << (m - 1)) * n

        for j in range(1, m):
            val = 1 << (m - 1 - j)
            set_count = 0

            for i in range(n):
                if grid[i][j] == grid[i][0]:
                    set_count += 1

            res += max(set_count, n - set_count) * val

        return res

class Solution:
    def minDominoRotations(self, tops, bottoms):
        res = float('inf')
        for val in range(1, 7):
            top_swaps = bottom_swaps = 0
            valid = True
            for t, b in zip(tops, bottoms):
                if t != val and b != val:
                    valid = False
                    break
                if t != val:
                    top_swaps += 1
                if b != val:
                    bottom_swaps += 1
            if valid:
                res = min(res, top_swaps, bottom_swaps)
        return -1 if res == float('inf') else res

class Solution:
    def balanceBST(self, root: TreeNode) -> TreeNode:
        self.sortedArr = []
        self.inorderTraverse(root)
        return self.sortedArrayToBST(0, len(self.sortedArr) - 1)

    def inorderTraverse(self, root: TreeNode) -> None:
        if not root:
            return
        self.inorderTraverse(root.left)
        self.sortedArr.append(root)
        self.inorderTraverse(root.right)

    def sortedArrayToBST(self, start: int, end: int) -> TreeNode:
        if start > end:
            return None
        mid = (start + end) // 2
        root = self.sortedArr[mid]
        root.left = self.sortedArrayToBST(start, mid - 1)
        root.right = self.sortedArrayToBST(mid + 1, end)
        return root

class Solution:
    def sortMatrix(self, matrix):
        # Dictionary to store diagonals, where key is the difference of row and column index
        diagonal_map = {}
        rows, cols = len(matrix), len(matrix[0])

        # Traverse the matrix and group elements by their diagonal (row - col)
        for i in range(rows):
            for j in range(cols):
                key = i - j
                if key not in diagonal_map:
                    diagonal_map[key] = []
                diagonal_map[key].append(matrix[i][j])

        # Sort each diagonal: negative keys (upper diagonals) in ascending order,
        # positive keys (lower diagonals) in descending order
        for key in diagonal_map:
            if key < 0:
                diagonal_map[key].sort()
            else:
                diagonal_map[key].sort(reverse=True)

        # Populate the sorted values back into the matrix
        for i in range(rows):
            for j in range(cols):
                key = i - j
                matrix[i][j] = diagonal_map[key].pop(0)

        return matrix

def minOperations(grid, x):
    all_nums = [num for row in grid for num in row]
    mod = all_nums[0] % x

    if any(num % x != mod for num in all_nums):
        return -1

    all_nums.sort()
    median = all_nums[len(all_nums) // 2]
    return sum(abs(num - median) // x for num in all_nums)

