class Solution:
    def pseudoPalindromicPaths(self, root):
        count = 0
        stack = [(root, 0)]

        while stack:
            node, path = stack.pop()

            if node:
                path ^= 1 << node.val

                if not node.left and not node.right:
                    if path & (path - 1) == 0:
                        count += 1
                else:
                    stack.append((node.right, path))
                    stack.append((node.left, path))

        return count

class Solution:
    def checkOverlap(self, radius: int, xCenter: int, yCenter: int, x1: int, y1: int, x2: int, y2: int) -> bool:
        nearestX = max(x1, min(x2, xCenter))
        nearestY = max(y1, min(y2, yCenter))

        dist = (nearestX - xCenter) ** 2 + (nearestY - yCenter) ** 2
        return dist <= radius * radius

from itertools import accumulate
from typing import List, Generator


class Solution:
    """
    Time:   O(log(n) + m)
    Memory: O(log(n))

    where m - length of queries
    """

    MAX_POWER = 32
    MOD = 10 ** 9 + 7

    def productQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        cum_powers = list(accumulate(self._to_powers(n), initial=1))
        return [pow(2, cum_powers[r + 1] - cum_powers[l], self.MOD) for l, r in queries]

    @classmethod
    def _to_powers(cls, num: int) -> Generator:
        return (p for p in range(cls.MAX_POWER) if num & (1 << p) != 0)

class SnapshotArray:

    def __init__(self, length: int):
        self.cur_id = 0
        self.curVals = [0] * length
        self.snapIdArr = [[-1] for _ in range(length)]
        self.arrVal = [[0] for _ in range(length)]
        self.modified = set()

    def set(self, index: int, val: int) -> None:
        if val == self.arrVal[index][-1]:
            if index in self.modified: self.modified.remove(index)
            return
        self.curVals[index] = val
        if index not in self.modified: self.modified.add(index)

    def snap(self) -> int:
        for idx in self.modified:
            self.snapIdArr[idx].append(self.cur_id)
            self.arrVal[idx].append(self.curVals[idx])
        self.modified.clear()
        self.cur_id += 1
        return self.cur_id - 1

    def get(self, index: int, snap_id: int) -> int:
        arr = self.snapIdArr[index]
        l, r = 0, len(arr)
        while l < r:
            m = (l + r) // 2
            if arr[m] <= snap_id:
                l = m + 1
            else: r = m
        return self.arrVal[index][l-1]

import heapq
def minimumCost(start, target, specialRoads):
    filteredRoads = []
    for road in specialRoads:
        a, b, c, d, cost = road
        if cost < abs(a - c) + abs(b - d):
            filteredRoads.append([a, b, c, d, cost])
    dist = {(start[0], start[1]): 0}
    heap = [(0, start[0], start[1])]
    while heap:
        currdist, x, y = heapq.heappop(heap)
        for road in filteredRoads:
            a, b, c, d, cost = road
            if dist.get((c, d), float('inf')) > currdist + abs(x - a) + abs(y - b) + cost:
                dist[(c, d)] = currdist + abs(x - a) + abs(y - b) + cost
                heapq.heappush(heap, (dist[(c, d)], c, d))
    res = abs(target[0] - start[0]) + abs(target[1] - start[1])
    for road in filteredRoads:
        a, b, c, d, cost = road
        res = min(res, dist.get((c, d), float('inf')) + abs(target[0] - c) + abs(target[1] - d))
    return res

class Solution:
    def longestSubstring(self, s: str, k: int) -> int:
        return max(self.longestSubstring(t,k) for t in split(f'[{q}]',s)) if (q:=''.join(c for c,f in Counter(s).items() if f<k)) else len(s)

class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        def helper(line: float, squares: List[List[int]]) -> float:
            aAbove = 0.0
            aBelow = 0.0
            for sq in squares:
                x, y, l = sq
                total = l * l
                if line <= y:
                    aAbove += total
                elif line >= y + l:
                    aBelow += total
                else:
                    # The line intersects the square.
                    aboveHeight = (y + l) - line
                    belowHeight = line - y
                    aAbove += l * aboveHeight
                    aBelow += l * belowHeight
            return aAbove - aBelow

        lo = 0
        hi = 2*1e9
        
        for _ in range(60):
            mid = (lo + hi) / 2.0
            diff = helper(mid, squares)
            

            if diff > 0:
                lo = mid
            else:
                hi = mid
        
        return hi

def min_changes(s):
    count = 0
    i = 0
    while i < len(s) - 1:
        if s[i] != s[i + 1]:
            count += 1
        i += 2
    return count

class Solution:
    def longestCommonPrefix(self, words: List[str]) -> List[int]:

        n = len(words)
        suffix = [0] * n
        prefix = [0] * n

        if n == 1:
            return [0]
            
        def lcp(s, t):
            n = min(len(s), len(t))
            i = 0
            while i < n:
                if s[i] != t[i]:
                    return i
                i+=1
                
            return i
            
        for i in range(n-2, -1, -1):
            suffix[i] = max(suffix[i+1], lcp(words[i], words[i+1]))

        for i in range(1, n):
            prefix[i] = max(prefix[i-1], lcp(words[i], words[i-1]))

        ans = []
        
        for i in range(n):
            if i-1 < 0:
                ans.append(suffix[i+1])
                continue
                
            if i+1 == n:
                ans.append(prefix[i-1])
                continue

            ans.append(max(prefix[i-1], suffix[i+1], lcp(words[i-1], words[i+1])))

        return ans

class Solution:
    def maxFreeTime(self, eventTime: int, startTime: List[int], endTime: List[int]) -> int:
        size = len(startTime)
        gapsArr,left = [],0
        for i in range(size):
            gap = startTime[i] - left
            gapsArr.append(gap)
            left = endTime[i]
        gapsArr.append(eventTime - endTime[-1])
        maxGapPrefix,maxGapSuffix = [0 for i in range(size)],[0 for i in range(size)]
        maxGapPrefix[0] = gapsArr[0]
        maxGapSuffix[size-1] = gapsArr[-1]

        # calculate left right max
        for i in range(1,size):
            maxGapPrefix[i]= max(maxGapPrefix[i-1],gapsArr[i])
        for i in range(size-1,0,-1):
            maxGapSuffix[i-1]= max(maxGapSuffix[i],gapsArr[i])
        
        ans = 0
        for i in range(size):
            curr = gapsArr[i]+gapsArr[i+1]
            barSize = endTime[i] - startTime[i]
            isValid = False
            if(i-1 >= 0):
                isValid = isValid or maxGapPrefix[i-1] >= barSize
            if(i+1 < size):
                isValid = isValid or maxGapSuffix[i+1] >= barSize
            if(isValid):
                curr += barSize
            ans = max(ans, curr)
        return ans

class Solution:
    def eraseOverlapIntervals(self, intervals: List[List[int]]) -> int:
        res = 0

        intervals.sort(key=lambda x: x[1])
        prev_end = intervals[0][1]

        for i in range(1, len(intervals)):
            if prev_end > intervals[i][0]:
                res += 1
            else:
                prev_end = intervals[i][1]
        
        return res

def minimumLines(self, A: List[List[int]]) -> int:
    n = len(A)
    res = n - 1
    A.sort()
    for i in range(1, n - 1):
        a, b, c = A[i-1], A[i], A[i+1]
        if (b[0] - a[0]) * (c[1] - b[1]) == (c[0] - b[0]) * (b[1] - a[1]):
            res -= 1
    return res

class Solution:
    def solveEquation(self, equation: str) -> str:
        def parse(expr):
            expr = expr.replace('-', '+-')  # Make every term explicit with '+'
            tokens = expr.split('+')
            x_coeff = 0
            const = 0
            for token in tokens:
                if not token:
                    continue
                if 'x' in token:
                    if token == 'x':
                        x_coeff += 1
                    elif token == '-x':
                        x_coeff -= 1
                    else:
                        x_coeff += int(token.replace('x', ''))
                else:
                    const += int(token)
            return x_coeff, const

        left, right = equation.split('=')
        left_x, left_const = parse(left)
        right_x, right_const = parse(right)

        # Move x terms to one side and constants to the other
        total_x = left_x - right_x
        total_const = right_const - left_const

        if total_x == 0:
            if total_const == 0:
                return "Infinite solutions"
            else:
                return "No solution"
        else:
            x_val = total_const // total_x
            return f"x={x_val}"

from collections import deque

class Solution:
    def deepestLeavesSum(self, root):
        if not root:
            return 0

        queue = deque([root])
        last_level = []

        while queue:
            level_size = len(queue)
            current_level = []

            for _ in range(level_size):
                node = queue.popleft()
                current_level.append(node.val)

                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)

            last_level = current_level

        return sum(last_level)

class Solution:
    def eliminateMaximum(self, dist: List[int], speed: List[int]) -> int:
        heap = []
        for i in range(len(dist)):
            heapq.heappush(heap, dist[i] / speed[i])
        
        res = 0

        while heap:
            if heapq.heappop(heap) <= res:
                break
            res += 1
        
        return res

class Solution:
    def maskPII(self, s: str) -> str:
        if "@" in s:
            name,domain=s.split("@")
            name=name.lower()
            domain=domain.lower()
            name=name[0]+"*****"+name[-1]
            return name+"@"+domain  
        else:
            gg=""
            for x in s:
                if x.isdigit():
                    gg+=x
            l=len(gg)
            if l>10:
                return "+"+"*"*(l-10)+"-***-***-"+gg[-4:]
            return "***-***-"+gg[-4:]

class Solution:
    def maxStrength(self, nums: List[int]) -> int:
        contains_zero = False
        positive = []
        negative = []

        for num in nums:
            if num > 0:
                positive.append(num)
            elif num < 0:
                negative.append(num)
            else:
                contains_zero = True

        # If the product of negative numbers is negative
        if len(negative) & 1:
            # If there is more than one negative number,
            # then their product can be positive.
            if len(negative) > 1:
                negative.remove(max(negative))
            # If not, then the product of positive numbers is sufficient
            elif positive:
                return prod(positive)
            # If not again, then zero is greater than negative numbers.
            elif contains_zero:
                return 0
            # If again not, then return the maximum among the negative
            else:
                return max(negative)

        # Consists of zeros only
        if not (negative or positive):
            return 0

        return prod(negative) * prod(positive)

from typing import List


class Solution:
    def atLeastK(self, nums: List[int], k: int) -> int:
        left = 0
        current = 0
        res = 0
        for i in range(len(nums)):
            if nums[i] % 2 == 1:
                current += 1

            while current >= k:
                if nums[left] % 2 == 1:
                    current -= 1
                left += 1

            res += left
        return res

    def numberOfSubarrays(self, nums: List[int], k: int) -> int:
        return self.atLeastK(nums, k) - self.atLeastK(nums, k + 1)


