class Solution:
    def minimizeStringValue(self, s: str) -> str:
        freq = [0]*26
        pq = []
        for i in range(len(s)):
            if s[i] != '?':
                freq[ord(s[i]) - ord('a')] += 1
        
        for i in range(26):
            heapq.heappush(pq, (freq[i], chr(ord('a') + i)))
        
        temp = ""
        for i in range(len(s)):
            if s[i] == '?':
                it = heapq.heappop(pq)
                toInsert = it[1]
                frequency = it[0]
                temp += toInsert
                heapq.heappush(pq, (frequency + 1, toInsert))
        
        temp = ''.join(sorted(temp))
        j = 0
        s = list(s)
        for i in range(len(s)):
            if s[i] == '?':
                s[i] = temp[j]
                j += 1
        
        return ''.join(s)

class Solution:
    def miceAndCheese(self, reward1: List[int], reward2: List[int], k: int) -> int:
        output = 0
        n = len(reward1)
        heap = []
        for i in range(n):
            heap.append((reward2[i] - reward1[i], i))
            
        heapq.heapify(heap)
        visited = set()
        while k:
            k -= 1
            _, idx = heapq.heappop(heap)
            visited.add(idx)
            output += reward1[idx]
            
        # If there is anything left that has not been taken, we take it from reward2.
        for idx, val in enumerate(reward2):
            if idx in visited:
                continue
            output += val
        
        return output

class Solution:
    def gridGame(self, grid: List[List[int]]) -> int:
        min_result = float('inf')
        row1_sum = sum(grid[0])
        row2_sum = 0
        
        for i in range(len(grid[0])):
            row1_sum -= grid[0][i]
            min_result = min(min_result, max(row1_sum, row2_sum))
            row2_sum += grid[1][i]
        
        return min_result

class Solution:
    def numTeams(self, rating: List[int]) -> int:
        n = len(rating)
        if n < 3:
            return 0
        
        soldiers = sorted([(r, i) for i, r in enumerate(rating)])
        index_map = [0] * n
        for i, (_, idx) in enumerate(soldiers):
            index_map[idx] = i
        
        def count_teams(ascending: bool) -> int:
            bit = [0] * (n + 1)
            teams = 0
            
            for i in range(n):
                rank = index_map[i] + 1
                left = self.get_sum(bit, rank - 1) if ascending else self.get_sum(bit, n) - self.get_sum(bit, rank)
                right = n - rank - (self.get_sum(bit, n) - self.get_sum(bit, rank)) if ascending else rank - 1 - self.get_sum(bit, rank - 1)
                teams += left * right
                self.update(bit, rank, 1)
            
            return teams
        
        return count_teams(True) + count_teams(False)
    
    def update(self, bit: List[int], index: int, val: int) -> None:
        while index < len(bit):
            bit[index] += val
            index += index & (-index)
    
    def get_sum(self, bit: List[int], index: int) -> int:
        total = 0
        while index > 0:
            total += bit[index]
            index -= index & (-index)
        return total

class Solution:
    def numOfSubarrays(self, arr: List[int]) -> int:
        oddCount, prefixSum, mod = 0, 0, 1_000_000_007
        for a in arr:
            prefixSum += a
            oddCount += prefixSum % 2
        oddCount += (len(arr) - oddCount) * oddCount
        return oddCount % mod

class Solution:
    def carPooling(self, trips: List[List[int]], capacity: int) -> bool:
        destionations = [0] * 1001
        for passengers, start, end in trips:
            destionations[start] += passengers
            destionations[end] -= passengers
        s = 0
        for dest in destionations:
            s += dest
            if s > capacity:
                return False
        return True

