class Solution:
    def peopleAwareOfSecret(self, n: int, d: int, f: int) -> int:
        dp, md = [1] + [0] * (f - 1), 10**9 + 7
        for i in range(1, n):
            dp[i % f] = (md + dp[(i + f - d) % f] - dp[i % f] + (0 if i == 1 else dp[(i - 1) % f])) % md
        return sum(dp) % md

class Solution:
    def getWordsInLongestSubsequence(self, words, groups):
        from functools import lru_cache

        def hamming_dist(w1, w2):
            return sum(a != b for a, b in zip(w1, w2)) == 1

        n = len(words)
        @lru_cache(None)
        def dfs(i, last_group, last_word):
            if i == n:
                return []
            take = []
            if len(words[i]) == len(last_word) and hamming_dist(last_word, words[i]) and groups[i] != last_group:
                take = [words[i]] + dfs(i + 1, groups[i], words[i])
            skip = dfs(i + 1, last_group, last_word)
            return take if len(take) > len(skip) else skip

        res = []
        for i in range(n):
            curr = [words[i]] + dfs(i + 1, groups[i], words[i])
            if len(curr) > len(res):
                res = curr
        return res

class Solution:
    def minMoves(self,a,b,c):
        x=min(a,b,c)
        z=max(a,b,c)
        y=(a+b+c)-(x+z)
        if x+1==y and y+1==z:
            return 0
        if x+1==y or y+1==z:
            return 1
        return min((z-y-1),(y-x-1),2)
        
        
    def maxMoves(self,a,b,c):
        x=min(a,b,c)
        z=max(a,b,c)
        y=(a+b+c)-(x+z)
        return (z-y-1)+(y-x-1)
        
    def numMovesStones(self, a: int, b: int, c: int) -> List[int]:
        return [self.minMoves(a,b,c),self.maxMoves(a,b,c)]

