class Solution:
    def maximumJumps(self, nums: List[int], target: int) -> int:
        dp = [-1] * len(nums)
        dp[0] = 0

        for i in range(1, len(nums)):
            for j in range(i - 1, -1, -1):
                if -target <= nums[i] - nums[j] and nums[i] - nums[j] <= target:
                    if dp[j] > -1:
                        dp[i] = max(dp[i], dp[j] + 1)

        return dp[-1]

def getSubarrayBeauty(self, nums: List[int], k: int, x: int) -> List[int]:
    counter, ans = [0] * 50, [0] * (len(nums) - k + 1)
    for i in range(len(nums)):
        if nums[i] < 0: counter[nums[i] + 50] += 1
        if i - k >= 0 and nums[i - k] < 0: counter[nums[i - k] + 50] -= 1
        if i - k + 1 < 0: continue
        count = 0
        for j in range(50):
            count += counter[j]
            if count >= x:
                ans[i - k + 1] = j - 50
                break
    return ans

class Solution:
    def furthestBuilding(self, heights: List[int], bricks: int, ladders: int) -> int:
        n = len(heights)
        return self.solve(heights, 0, bricks, ladders)

    def solve(self, heights: List[int], i: int, bricks: int, ladders: int) -> int:
        if i == len(heights) - 1:
            return i
        diff = heights[i + 1] - heights[i]
        if diff > 0:
            ans = i
            if bricks >= diff:
                ans = max(ans, self.solve(heights, i + 1, bricks - diff, ladders))
            if ladders > 0:
                ans = max(ans, self.solve(heights, i + 1, bricks, ladders - 1))
            return ans
        else:
            return self.solve(heights, i + 1, bricks, ladders)

class Solution:
    def checkIfPrerequisite(self, numCourses: int, prerequisites: List[List[int]], queries: List[List[int]]) -> List[bool]:
        adj = [[] for _ in range(numCourses)]
        indegree = [0] * numCourses
        for p in prerequisites:
            adj[p[0]].append(p[1])
            indegree[p[1]] += 1
        
        q = deque()
        for i in range(numCourses):
            if indegree[i] == 0:
                q.append(i)
        
        mp = defaultdict(set)
        while q:
            curr = q.popleft()
            for next_course in adj[curr]:
                mp[next_course].add(curr)
                mp[next_course].update(mp[curr])
                indegree[next_course] -= 1
                if indegree[next_course] == 0:
                    q.append(next_course)
        
        return [q[0] in mp[q[1]] for q in queries]

