import heapq

class Solution:
    def find_prime(self, isprime, n):
        isprime[0] = isprime[1] = False # 0 and 1 are not prime numbers
        
        for i in range(2, int(n**0.5) + 1):
            if isprime[i]:
                for j in range(i * i, n):
                    isprime[j] = False # Mark all multiples of i as non-prime

    def find_node(self, n):
        neighbors = []
        
        i = 1
        while i <= n:
            d = (n // i) % 10 # Extract the current digit
            
            # Decrease the current digit if possible
            if d > 0:
                neighbors.append(n - i)
            
            # Increase the current digit if possible
            if d < 9:
                neighbors.append(n + i)
            
            i *= 10

        return neighbors

    def minOperations(self, n, m):
        MAX = 10000 # Limit for prime computation
        INF = float('inf') # Represent unreachable distances
        
        # Step 1: Precompute all primes up to MAX
        isprime = [True] * MAX
        self.find_prime(isprime, MAX)
        
        # Edge case: If starting or ending node is prime, return -1
        if isprime[n] or isprime[m]:
            return -1

        # Step 2: Initialize distance array and priority queue
        dist = [INF] * MAX
        pq = []
        
        dist[n] = 0
        heapq.heappush(pq, (dist[n], n))

        # Step 3: Dijkstra's algorithm to find shortest path
        while pq:
            dis, num = heapq.heappop(pq)
            
            # Skip processing if the node is prime
            if isprime[num]:
                continue
            
            # Explore all neighboring nodes
            for neighbor in self.find_node(num):
                # Skip processing if the neighbor is prime
                if isprime[neighbor]:
                    continue
                
                # Relax the distance for the neighbor
                if dist[neighbor] > dis + num:
                    dist[neighbor] = dis + num
                    heapq.heappush(pq, (dist[neighbor], neighbor))

        # Step 4: Return the result
        return -1 if dist[m] == INF else m + dist[m]

class TrieNode:
    def __init__(self):
        self.children = dict()                        # children nodes
        self.val = 0                                  # end value 

class Trie:
    def __init__(self, n):
        self.root = TrieNode()                        # root node
        self.n = n                                    # max length of all numbers
        
    def add_num(self, num):
        node = self.root 
        for shift in range(self.n, -1, -1):           # only shift self.n bits 
            val = 1 if num & (1 << shift) else 0      # verify bit from left to right 
            if val not in node.children:
                node.children[val] = TrieNode()
            node = node.children[val]
        node.val = num
        
class Solution:
    def findMaximumXOR(self, nums: List[int]) -> int:
        max_len = len(bin(max(nums))) - 2             # get max length of all numbers' binary
        trie = Trie(max_len)
        for num in nums: trie.add_num(num)            # build trie
            
        ans = 0
        for num in nums:                              # for each num, find the number which can create max value with num using XOR
            node = trie.root 
            for shift in range(max_len, -1, -1):
                val = 1 if num & (1 << shift) else 0  # verify bit from left to right
                node = node.children[1-val] if 1-val in node.children else node.children[val] # try opposite bit first, otherwise use same bit
            ans = max(ans, num ^ node.val)            # maintain maximum
        return ans

class Solution:
    def findUnsortedSubarray(self, nums: List[int]) -> int:
        
        nums_sorted = list(sorted(nums))
        n = len(nums)
        
        i, j = -1, -1

        for i in range(n):
            if nums_sorted[i] != nums[i]:
                break
        
        for j in range(n-1, -1, -1):
            if nums_sorted[j] != nums[j]:
                break
        
        if i < j:
            return j-i+1
        
        return 0

class MyCalendarTwo:
    def __init__(self):
        # List to hold the booked intervals
        self.bookings = []
        
    def book(self, start: int, end: int) -> bool:
        # Check for overlaps with existing bookings
        for a, b in self.bookings:
            # Check if the new booking overlaps with the existing interval
            if start < b and end > a:
                # Calculate the overlapping sub-interval
                new_start = max(a, start)
                new_end = min(b, end)
                
                # Check if the sub-interval overlaps more than once
                if self.check(new_start, new_end):
                    return False  # Overlapping more than once, booking fails
        
        # If there are no conflicts, add the booking
        self.bookings.append((start, end))
        return True  # Booking successful
    
    def check(self, start: int, end: int) -> bool:
        overlap_count = 0
        
        for a, b in self.bookings:
            # Check for strict overlap
            if start < b and end > a:
                overlap_count += 1
                if overlap_count == 2:
                    return True  # Found more than one overlap
        
        return False  # No overlapping found

class Solution:
