class Solution:
    def checkArray(self, nums: List[int], k: int) -> bool:
        n = len(nums)
        pref = [0]*(n+1)
        ac = 0
        for i in range(0,n):
            ac-=pref[i]
            nums[i]-=ac

            if nums[i]<0:
                return False
            if i+k<=n:
                ac+=nums[i]
                pref[i+k]+=nums[i]
                nums[i] = 0
            elif nums[i]>0:
                return False

        return True

class Solution:
    def mergeTriplets(self, triplets: List[List[int]], target: List[int]) -> bool:

        contains_target = [False, False, False]

        for row_index in range(len(triplets)): #check each triplet
            exceeds_target = False # valid / invalid triplet
            targets_index = [] # list of target indicies in triplet
            for col_index in range(len(triplets[0])): #check each index
                if triplets[row_index][col_index] == target[col_index]:
                    targets_index.append(col_index) # contains one of the target values
                elif triplets[row_index][col_index] > target[col_index]:
                    exceeds_target = True # would cause us to exceed one of the target values
            
            if len(targets_index) > 0 and not exceeds_target:
                for target_index in targets_index: # unpack valid indicies 
                    contains_target[target_index] = True
            
            if contains_target == [True, True, True]:
                return True
        
        return False

class Solution:
    def findAllRecipes(self, recipes: List[str], ingredients: List[List[str]], supplies: List[str]) -> List[str]:
        available_supplies = set(supplies)
        
        recipe_to_ingredients = {recipes[i]: ingredients[i] for i in range(len(recipes))}
        
        visited = {}
        result = []
        
        def can_make(recipe):
            if recipe in visited and visited[recipe] == 0:
                return False
                
            if recipe in visited and visited[recipe] == 1:
                return True
                
            if recipe in available_supplies:
                return True
                
            if recipe not in recipe_to_ingredients:
                return False
                
            visited[recipe] = 0
            
            for ingredient in recipe_to_ingredients[recipe]:
                if not can_make(ingredient):
                    visited[recipe] = -1
                    return False
                    
            visited[recipe] = 1
            result.append(recipe)
            return True
        
        for recipe in recipes:
            can_make(recipe)
        
        return [recipe for recipe in recipes if recipe in visited and visited[recipe] == 1]

class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:

        def findArea(nums: tuple)-> int:

            (x1,y1), (x2,y2), (x3,y3), (x4,y4) = nums 

            if not (x1,x3, y1,y2) == (x2,x4, y3,y4): return -1 

            for point in points:
                if point in nums: continue 
                if x1 <= point[0] <= x3 and y1 <= point[1] <= y2: return -1

            return (x3 - x1) * (y2 - y1)

        points.sort()
        return max(map(findArea, combinations(points,4)))

