class Solution:
    def findRedundantDirectedConnection(self, edges: List[List[int]]) -> List[int]:
	
        unionList = list(range(len(edges)+1))
        
        def find(x):
            if x == unionList[x]:
                return x
            return find(unionList[x])
        
        def union(x,y):
            if find(x) != find(y):
                unionList[x] = y
         
		#check and saving the last edge in loop
        loop = None
		
		#check parent
        parent = {}
        for i,j in edges:
            parent.setdefault(j,[]).append(i)
            if find(i) == find(j):
                loop = [i,j]
            union(i,j)
			
		
		#get the node which has more than one parent
		doubleParent = [i for i in parent if len(parent[i]) > 1]
        hasDoubleParent = len(doubleParent)
		
        #which situation we are? 
        if not hasDoubleParent and loop:
            return loop
			# simple,return the edge in loop
        elif hasDoubleParent and not loop:
            return [parent[doubleParent[0]][1],doubleParent[0]]
			# easy, return the edge between node with second parent
		else:
			# get first edge and second edge(one of them should be removed)
			firstEdge = [parent[doubleParent[0]][0],doubleParent[0]]
            secondEdge = [parent[doubleParent[0]][1],doubleParent[0]]
			
			#remove second edge and check there is a loop or not
            deleteSecondEdge = edges[:]
            deleteSecondEdge.remove(secondEdge)
            unionList = list(range(len(edges)+1))
            
			
            for i,j in deleteSecondEdge:
                if find(i) == find(j):
				# opps,there is still a loop, we should remove first edge, so return it 
                    return firstEdge
                union(i,j)
			# seems like remove second edge works.
            return secondEdge

import itertools as it

class Solution:
    def judgePoint24(self, nums: List[int]) -> bool:
        if len(nums) == 1:
            return round(nums[0], 4) == 24
        else:
            for (i, m), (j, n) in it.combinations(enumerate(nums), 2):
                    new_nums = [x for t, x in enumerate(nums) if i != t != j]
                    inter = {m+n, abs(m-n), n*m}
                    if n != 0: inter.add(m/n)
                    if m != 0: inter.add(n/m)
                    
                    if any(self.judgePoint24(new_nums + [x]) for x in inter):
                        return True
            
            return False

class Solution:
    def findKthNumber(self, m: int, n: int, k: int) -> int:
        lo, hi = 1, m*n
        while lo < hi:
            mid, count = (lo+hi)//2, 0
            # check how many numbers are smaller than mid
            for i in range(1, m+1):
                count += n if n<mid//i else mid//i
            if count>=k:  # target <= mid
                hi = mid
            else:  # target > mid
                lo = mid+1
        return lo

class Solution:
    def strangePrinter(self, s: str) -> int:
        n = len(s)
        dp = [[-1] * n for _ in range(n)]
        return self.Util(0, n - 1, s, dp)

    def Util(self, i: int, j: int, s: str, dp: list) -> int:
        if i > j:
            return 0

        if dp[i][j] != -1:
            return dp[i][j]

        first_letter = s[i]
        # If the current character is not repeated in the rest of the string
        answer = 1 + self.Util(i + 1, j, s, dp)
        for k in range(i + 1, j + 1):
            # If repeated then update the answer
            if s[k] == first_letter:
                # Splitting from i -> k - 1 (remove the last character)
                # and from k + 1 -> j             
                better_answer = self.Util(i, k - 1, s, dp) + self.Util(k + 1, j, s, dp)
                answer = min(answer, better_answer)
        dp[i][j] = answer
        return answer

class Solution:
    def smallestRange(self, nums: List[List[int]]) -> List[int]:
        heap = []
        cur_max = float('-inf')
        for i in range(len(nums)):
            heapq.heappush(heap, (nums[i][0], i, 0)) 
            cur_max = max(cur_max, nums[i][0])
        small = [float('-inf'), float('inf')]
        while heap:
            cur_min, list_idx, i = heapq.heappop(heap)
            if cur_max - cur_min < small[1] - small[0]:
                small = [cur_min, cur_max]
            if i + 1 < len(nums[list_idx]):
                nxt = nums[list_idx][i + 1]
                heapq.heappush(heap, (nxt, list_idx, i+1))
                cur_max = max(cur_max, nxt)
            else:
                break
        return small

class Solution:
    def scheduleCourse(self, courses: List[List[int]]) -> int:
        courses.sort(key=lambda c: c[1])
        A, curr = [], 0
        for dur, ld in courses:
            heapq.heappush(A,-dur)
            curr += dur
            if curr > ld: curr += heapq.heappop(A)
        return len(A)

class Solution:
    def kInversePairs(self, n: int, k: int) -> int:
        dp = [[0] * 1001 for _ in range(1001)]
        dp[0][0] = 1

        for i in range(1, n + 1):
            for j in range(0, k + 1):
                for x in range(0, min(j, i - 1) + 1):
                    if j - x >= 0:
                        dp[i][j] = (dp[i][j] + dp[i - 1][j - x]) % 1000000007

        return dp[n][k]

class Solution:
    def findIntegers(self, n: int) -> int:
        # f stores the fibonacci numbers
        f = [1, 2]
        for i in range(2, 30):
            f.append(f[-1]+f[-2])
        
        # last_seen tells us if there was a one right before. 
        # If that is the case, we are done then and there!
        # ans is the answer
        ans, last_seen = 0, 0
        for i in reversed(range(30)):
            if (1 << i) & n: # is the ith bit set?
                ans += f[i]
                if last_seen: 
                    ans -= 1
                    break
                last_seen = 1
            else:
                last_seen = 0
        return ans+1

class Solution:
    def nearestPalindromic(self, numberStr: str) -> str:
        number = int(numberStr)
        if number <= 10:
            return str(number - 1)
        if number == 11:
            return "9"

        length = len(numberStr)
        leftHalf = int(numberStr[:(length + 1) // 2])

        palindromeCandidates = [
            self.generatePalindromeFromLeft(leftHalf - 1, length % 2 == 0),
            self.generatePalindromeFromLeft(leftHalf, length % 2 == 0),
            self.generatePalindromeFromLeft(leftHalf + 1, length % 2 == 0),
            10**(length - 1) - 1,
            10**length + 1
        ]

        nearestPalindrome = 0
        minDifference = float('inf')

        for candidate in palindromeCandidates:
            if candidate == number:
                continue
            difference = abs(candidate - number)
            if difference < minDifference or (difference == minDifference and candidate < nearestPalindrome):
                minDifference = difference
                nearestPalindrome = candidate

        return str(nearestPalindrome)

    def generatePalindromeFromLeft(self, leftHalf: int, isEvenLength: bool) -> int:
        palindrome = leftHalf
        if not isEvenLength:
            leftHalf //= 10
        while leftHalf > 0:
            palindrome = palindrome * 10 + leftHalf % 10
            leftHalf //= 10
        return palindrome


