class Solution:
    def palindromePairs(self, words: List[str]) -> List[List[int]]:
        backward, res = {}, []
        for i, word in enumerate(words):
            backward[word[::-1]] = i

        for i, word in enumerate(words):
            
            if word in backward and backward[word] != i:
                res.append([i, backward[word]])
                
            if word != "" and "" in backward and word == word[::-1]:
                res.append([i, backward[""]])
                res.append([backward[""], i])
                
            for j in range(len(word)):
                if word[j:] in backward and word[:j] == word[j-1::-1]:
                    res.append([backward[word[j:]], i])
                if word[:j] in backward and word[j:] == word[:j-1:-1]:
                    res.append([i, backward[word[:j]]])
                    
        return res

class Solution:
def findItinerary(self, tickets: List[List[str]]) -> List[str]:
    graph = {}
    # Create a graph for each airport and keep list of airport reachable from it
    for src, dst in tickets:
        if src in graph:
            graph[src].append(dst)
        else:
            graph[src] = [dst]

    for src in graph.keys():
        graph[src].sort(reverse=True)
        # Sort children list in descending order so that we can pop last element 
        # instead of pop out first element which is costly operation
    stack = []
    res = []
    stack.append("JFK")
    # Start with JFK as starting airport and keep adding the next child to traverse 
    # for the last airport at the top of the stack. If we reach to an airport from where 
    # we can't go further then add it to the result. This airport should be the last to go 
    # since we can't go anywhere from here. That's why we return the reverse of the result
    # After this backtrack to the top airport in the stack and continue to traaverse it's children
    
    while len(stack) > 0:
        elem = stack[-1]
        if elem in graph and len(graph[elem]) > 0: 
            # Check if elem in graph as there may be a case when there is no out edge from an airport 
            # In that case it won't be present as a key in graph
            stack.append(graph[elem].pop())
        else:
            res.append(stack.pop())
            # If there is no further children to traverse then add that airport to res
            # This airport should be the last to go since we can't anywhere from this
            # That's why we return the reverse of the result
    return res[::-1]

class Solution:
    def minPatches(self, nums: List[int], n: int) -> int:
        miss = 1
        result = 0
        i = 0

        while miss <= n:
            if i < len(nums) and nums[i] <= miss:
                miss += nums[i]
                i += 1
            else:
                miss += miss
                result += 1

        return result

class Solution:
    def longestIncreasingPath(self, matrix: List[List[int]]) -> int:
        if not matrix or not matrix[0]:
            return 0
        rows, cols = len(matrix), len(matrix[0])
        dp =[[0] * cols for i in range(rows)]
        def dfs(i, j):
            if not dp[i][j]:
                val = matrix[i][j]
                dp[i][j] = 1 + max(
                    dfs(i - 1, j) if i and val > matrix[i - 1][j] else 0,
                    dfs(i + 1, j) if i < rows - 1 and val > matrix[i + 1][j] else 0,
                    dfs(i, j - 1) if j and val > matrix[i][j - 1] else 0,
                    dfs(i, j + 1) if j < cols - 1 and val > matrix[i][j + 1] else 0)
            return dp[i][j]
        
        for r in range(rows):
            for c in range(cols):
                dfs(r,c)
        return max(max(x) for x in dp)

# prefix-sum + hashmap | time complexity: O(n+(upper-lower+1)*n)
def countRangeSum(self, nums: List[int], lower: int, upper: int) -> int:
    cumsum = [0]
    for n in nums:
        cumsum.append(cumsum[-1]+n)
    
    import collections
    record = collections.defaultdict(int)
    
    res = 0
    for csum in cumsum:
        for target in range(lower,upper+1):
            if csum - target in record:
                res += record[csum - target]
        record[csum] +=1
    return res

class Solution:
    def countSmaller(self, nums: List[int]) -> List[int]:

        arr, ans = sorted(nums), []           #  <-- 1)
        
        for num in nums:
            i = bisect_left(arr,num)          #  <-- 2a)
            ans.append(i)                     #  <-- 2b)
            del arr[i]                        #  <-- 2c)
            
        return ans                            #  <-- 3)

class Solution:
    def maxCoins(self, nums: List[int]) -> int:
        nums = [1] + nums + [1]
        dp = [[0 for _ in range(len(nums))] for _ in range(len(nums))]
        
        for gap in range(len(nums)):
            for left in range(len(nums)-gap):
                right = left + gap
                
                res = 0
                for i in range(left+1, right):
                    coins = nums[left] * nums[i] * nums[right]
                    res = max(res, coins + dp[left][i] + dp[i][right])
                dp[left][right] = res
                
        return dp[0][len(nums)-1]

class Solution:
    def removeInvalidParentheses(self, s: str) -> List[str]:
        ## RC ##
        ## APPROACH : BACK-TRACKING ##
        ## Similar to Leetcode 32. Longest Valid Parentheses ##
        ## LOGIC ##
        #   1. use stack to find invalid left and right braces.
        #   2. if its close brace at index i , you can remove it directly to make it valid and also you can also remove any of the close braces before that i.e in the range [0,i-1]
        #   3. similarly for open brace, left over at index i, you can remove it or any other open brace after that i.e [i+1, end]
        #   4. if left over braces are more than 1 say 2 close braces here, you need to make combinations of all 2 braces before that index and find valid parentheses.
        #   5. so, we count left and right invalid braces and do backtracking removing them
        
		## TIME COMPLEXITY : O(2^N) ## (each brace has 2 options: exits or to be removed)
		## SPACE COMPLEXITY : O(N) ##

        def isValid(s):
            stack = []
            for i in range(len(s)):
                if( s[i] == '(' ):
                    stack.append( (i,'(') )
                elif( s[i] == ')' ):
                    if(stack and stack[-1][1] == '('):
                        stack.pop()
                    else:
                        stack.append( (i,')') )         # pushing invalid close braces also
            return len(stack) == 0, stack
        
        
        def dfs( s, left, right):
            visited.add(s)
            if left == 0 and right == 0 and isValid(s)[0]:  res.append(s)
            for i, ch in enumerate(s):
                if ch != '(' and ch != ')': continue                                    # if it is any other char ignore.
                if (ch == '(' and left == 0) or (ch == ')' and right == 0): continue    # if left == 0 then removing '(' will only cause imbalance. Hence, skip.
                if s[:i] + s[i+1:] not in visited:
                    dfs( s[:i] + s[i+1:], left - (ch == '('), right - (ch == ')') )
        
        stack = isValid(s)[1]
        lc = sum([1 for val in stack if val[1] == "("]) # num of left braces
        rc = len(stack) - lc
        
        res, visited = [], set()
        dfs(s, lc, rc)
        return res

class Solution:
    def addOperators(self, num: str, target: int) -> List[str]:
        L = len(num)
        ans = set()
        
        def backtrack(i, total, last, expr):
            if i == L:
                if total == target:
                    ans.add(expr)
                return
            
            for j in range(i, L):
                n = int(num[i:j+1])
                if i == 0:
                    backtrack(j+1, n, n, str(n))
                else:
                    backtrack(j+1, total + n, n, expr + '+' + str(n))
                    backtrack(j+1, total - n, -n, expr + '-' + str(n))
                    backtrack(j+1, total - last + last * n, last * n, expr + '*' + str(n))
                if n == 0:
                    break
                    
        backtrack(0, 0, 0, '')
        return list(ans)

class Solution:
    def numberToWords(self, num: int) -> str:
        if num == 0:
            return "Zero"
        ones = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine"]
        tens = ["", "Ten", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"]
        teens = ["Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"]
        suffixes = ["", "Thousand", "Million", "Billion", "Trillion", "Quadrillion", "Quintillion", "Sextillion", "Septillion", "Octillion", "Nonillion", "Decillion"]
        words = []
        i = 0
        while num > 0:
            triplet = num % 1000
            num = num // 1000
            if triplet == 0:
                i += 1
                continue
            temp = []
            if triplet // 100 > 0:
                temp.append(ones[triplet // 100])
                temp.append("Hundred")
            if triplet % 100 >= 10 and triplet % 100 <= 19:
                temp.append(teens[triplet % 10])
            else:
                if triplet % 100 >= 20:
                    temp.append(tens[triplet % 100 // 10])
                if triplet % 10 > 0:
                    temp.append(ones[triplet % 10])
            if i > 0:
                temp.append(suffixes[i])
            words = temp + words
            i += 1
        return " ".join(words)

import pandas as pd

def trips_and_users(trips: pd.DataFrame, users: pd.DataFrame) -> pd.DataFrame:
    banned = {}
    for ele in users.loc[:, ["users_id", "banned"]].values:
        if ele[1] == "Yes": banned[ele[0]] = True
        else: banned[ele[0]] = False
    day = []
    cancellation_rate = []
    ans = {}
    for ele in trips.loc[:, ["client_id", "driver_id", "status", "request_at"]].values:
        client_id, driver_id, status, request_at = ele
        if banned.get(client_id) or banned.get(driver_id):
            continue
        if ans.get(request_at) is None:
            ans[request_at] = [0, 0]
        if status == "completed":
            ans[request_at][0] += 1
        else:
          if ans[request_at][0] == 0 and str(request_at) != "2013-10-01":
              continue
        ans[request_at][1] += 1
    day = []
    out = []
    for key, val in ans.items():
        if val[1] == 0:
          continue
        day.append(key)
        out.append(round((val[1] - val[0]) / val[1], 2))
    return pd.DataFrame({"Day" : day, "Cancellation Rate": out})

class Solution:
    def countDigitOne(self, n: int) -> int:
        def count(add,n_digit):
            c = 0
            for d in range(0,n_digit+1):
                c += (d+add)*math.comb(n_digit,d)*9**(n_digit-d)
            return c
        res = 0
        n_list = [int(x) for x in str(n)]
        count_1 = 0
        for i in range(len(n_list)-1):
            if n_list[i] == 1:
                res += count(count_1,len(n_list)-i-1)
                count_1 += 1
            elif n_list[i] > 1:
                leading = n_list[i]-1
                res += count(count_1,len(n_list)-i-1)*leading+count(count_1+1,len(n_list)-i-1)
        res += count_1*(n_list[-1]+1)
        if n_list[-1] >= 1:
            res += 1
        return res

class Solution:
    def containsNearbyAlmostDuplicate(self, nums: List[int], k: int, t: int) -> bool:
        if t < 0: return False # edge case 
        
        seen = {}
        for i, x in enumerate(nums): 
            bkt = x//(t+1)
            if bkt in seen and i - seen[bkt][0] <= k: return True 
            if bkt-1 in seen and i - seen[bkt-1][0] <= k and abs(x - seen[bkt-1][1]) <= t: return True 
            if bkt+1 in seen and i - seen[bkt+1][0] <= k and abs(x - seen[bkt+1][1]) <= t: return True 
            seen[bkt] = (i, x) 
        return False

