class Solution:
    def findMin(self, nums: List[int]) -> int:
        N=len(nums)
        start=0
        end=N-1
        while start<end:
            mid=(start+end)//2
			# add this line to handle duplicate
            while nums[mid]==nums[end] and mid<end:
                end-=1
            if nums[mid]>nums[end]:
                start=mid+1
            else:
                end=mid
        return nums[start]

class Solution:
    def maxPoints(self, points: List[List[int]]) -> int:
        if len(points) <= 2:
            return len(points)
        
        def find_slope(p1, p2):
            x1, y1 = p1
            x2, y2 = p2
            if x1-x2 == 0:
                return inf
            return (y1-y2)/(x1-x2)
        
        ans = 1
        for i, p1 in enumerate(points):
            slopes = defaultdict(int)
            for j, p2 in enumerate(points[i+1:]):
                slope = find_slope(p1, p2)
                slopes[slope] += 1
                ans = max(slopes[slope], ans)
        return ans+1

def fun(s,dc,memo):
    if(s in memo):
        return memo[s]
    ans=[]
    if(dc[s]==1):
        ans=[s]
    for i in range(1,len(s)):
        if(dc[s[:i]]==1):
            a=fun(s[i:],dc,memo)
            for x in a:
                ans.append(s[:i]+" "+x)
    memo[s]=ans
    return ans
