class Solution(object):
    def minCut(self, s):
        """
        s="abcgcbafj"
        :type s: str
        :rtype: int
        """
      
        if s == s[::-1]:
            return 0
        
        for i in range(len(s)):
            if s[:i] == s[:i][::-1] and s[i:] == s[i:][::-1]:
                return 1
        
        l=len(s)
      
        #d=[[0 for i  in range(l)] for j in range(l)]
        x=[[0 for i  in range(l)] for j in range(l)]
        for i in range(l):
          for j in range(i,l):
            st=s[i:j+1]
            #d[i][j]=st
            x[i][j]= (st==st[::-1])
                      
            
        p=[0 for c in range(l)]
        for i in range(1,l):
          if x[0][i]:
            p[i]=0
          else:
            m=float("inf")
            for j in range(i,0,-1):
              if x[j][i]: 
                m=min(m,p[j-1])
            p[i]=m+1
        return p[-1]

from collections import defaultdict
from collections import deque
class Solution:
    def ladderLength(self, beginWord: str, endWord: str, wordList: List[str]) -> int:
        """
        :type beginWord: str
        :type endWord: str
        :type wordList: List[str]
        :rtype: int
        """
        if endWord not in wordList or not endWord or not beginWord or not wordList:
            return 0
        L = len(beginWord)
        all_combo_dict = defaultdict(list)
        for word in wordList:
            for i in range(L):
                all_combo_dict[word[:i] + "*" + word[i+1:]].append(word) 
        queue = deque([(beginWord, 1)])
        visited = set()
        visited.add(beginWord)
        while queue:
            current_word, level = queue.popleft()
            for i in range(L):
                intermediate_word = current_word[:i] + "*" + current_word[i+1:]
                for word in all_combo_dict[intermediate_word]:
                    if word == endWord:
                        return level + 1
                    if word not in visited:
                        visited.add(word)
                        queue.append((word, level + 1))
        return 0

	from collections import deque
	class Solution:
		def findLadders(self, beginWord: str, endWord: str, wordList: List[str]) -> List[List[str]]:
			if endWord not in wordList:return []
			wordList.append(beginWord)
			wordList.append(endWord)
			distance = {}


			self.bfs(endWord, distance, wordList)

			results = []
			self.dfs(beginWord, endWord, distance, wordList, [beginWord], results)

			return results

		def bfs(self, start, distance, w):
			distance[start] = 0
			queue = deque([start])
			while queue:
				word = queue.popleft()
				for next_word in self.get_next_words(word, w):
					if next_word not in distance:
						distance[next_word] = distance[word] + 1
						queue.append(next_word)

		def get_next_words(self, word, w):
			words = []
			for i in range(len(word)):
				for c in 'abcdefghijklmnopqrstuvwxyz':
					next_word = word[:i] + c + word[i + 1:]
					if next_word != word and next_word in w:
						words.append(next_word)
			return words

		def dfs(self, curt, target, distance, w, path, results):
			if curt == target:
				results.append(list(path))
				return

			for word in self.get_next_words(curt, w):
				if distance[word] != distance[curt] - 1:
					continue
				path.append(word)
				self.dfs(word, target, distance, w, path, results)
				path.pop()

class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        m = len(s)
        n = len(t)
        dp = [[0] * (n+1) for _ in range(m+1)]
        
        for i in range(m+1):
            dp[i][0] = 1
        
        """redundant, as we have initialised dp table with full of zeros"""
#         for i in range(1, n+1): 
#             dp[0][i] = 0
        
        for i in range(1, m+1):
            for j in range(1, n+1):
                dp[i][j] += dp[i-1][j] 			#if current character is skipped
                if s[i-1] == t[j-1]:
                    dp[i][j] += dp[i-1][j-1]	#if current character is used
        
        return dp[-1][-1]

class Solution:
    def isScramble(self, s1: str, s2: str) -> bool:
        n = len(s1)
        # Initialize a 3D table to store the results of all possible substrings of the two strings
        dp = [[[False for _ in range(n)] for _ in range(n)] for _ in range(n+1)]

        # Initialize the table for substrings of length 1
        for i in range(n):
            for j in range(n):
                dp[1][i][j] = s1[i] == s2[j]

        # Fill the table for substrings of length 2 to n
        for length in range(2, n+1):
            for i in range(n+1-length):
                for j in range(n+1-length):
                    # Iterate over all possible lengths of the first substring
                    for newLength in range(1, length):
                        # Check if the two possible splits of the substrings are scrambled versions of each other
                        dp1 = dp[newLength][i]
                        dp2 = dp[length-newLength][i+newLength]
                        dp[length][i][j] |= dp1[j] and dp2[j+newLength]
                        dp[length][i][j] |= dp1[j+length-newLength] and dp2[j]

        # Return whether the entire strings s1 and s2 are scrambled versions of each other
        return dp[n][0][0]

class Solution:
    def maximalRectangle(self, matrix: List[List[str]]) -> int:
        if not matrix:
            return 0
        
        rows, cols = len(matrix), len(matrix[0])
        heights = [0] * (cols + 1)  # Include an extra element for easier calculation
        max_area = 0
        
        for row in matrix:
            for i in range(cols):
                heights[i] = heights[i] + 1 if row[i] == '1' else 0
            
            # Calculate max area using histogram method
            stack = []
            for i in range(len(heights)):
                while stack and heights[i] < heights[stack[-1]]:
                    h = heights[stack.pop()]
                    w = i if not stack else i - stack[-1] - 1
                    max_area = max(max_area, h * w)
                stack.append(i)
        
        return max_area

class Solution:
    def largestRectangleArea(self, heights: List[int]) -> int:
        stack = [-1]
        max_area = 0

        for i in range(len(heights)):
            while stack[-1] != -1 and heights[i] <= heights[stack[-1]]:
                height = heights[stack.pop()]
                width = i - stack[-1] - 1
                max_area = max(max_area, height * width)
            stack.append(i)
        
        while stack[-1] != -1:
            height = heights[stack.pop()]
            width = len(heights) - stack[-1] - 1
            max_area = max(max_area, height * width)
        
        return max_area

class Solution:
    def minWindow(self, s: str, t: str) -> str:
        if len(s) < len(t):
            return ""
        needstr = collections.defaultdict(int)
        for ch in t:
            needstr[ch] += 1
        needcnt = len(t)
        res = (0, float('inf'))
        start = 0
        for end, ch in enumerate(s):
            if needstr[ch] > 0:
                needcnt -= 1
            needstr[ch] -= 1
            if needcnt == 0:
                while True:
                    tmp = s[start]
                    if needstr[tmp] == 0:
                        break
                    needstr[tmp] += 1
                    start += 1
                if end - start < res[1] - res[0]:
                    res = (start, end)
                needstr[s[start]] += 1
                needcnt += 1
                start += 1
        return '' if res[1] > len(s) else s[res[0]:res[1]+1]

def fullJustify(self, words, maxWidth):
    res, cur, num_of_letters = [], [], 0
    for w in words:
        if num_of_letters + len(w) + len(cur) > maxWidth:
            if len(cur) == 1:
                res.append( cur[0] + ' '*(maxWidth - num_of_letters) )
            else:
                num_spaces = maxWidth - num_of_letters
                space_between_words, num_extra_spaces = divmod( num_spaces, len(cur)-1)
                for i in range(num_extra_spaces):
                    cur[i] += ' '
                res.append( (' '*space_between_words).join(cur) )
            cur, num_of_letters = [], 0
        cur += [w]
        num_of_letters += len(w)
    res.append( ' '.join(cur) + ' '*(maxWidth - num_of_letters - len(cur) + 1) )
    return res

class BIT:
    def __init__(self, n):
        self.n = n
        self.l = [0] * (n + 1)
    def add(self, i, x):
        i += 1
        while i <= self.n:
            self.l[i] = max(x, self.l[i])
            i += i & -i
    def query(self, i):
        i += 1
        ans = 0
        while i:
            ans = max(ans, self.l[i])
            i -= i & -i
        return ans

from sortedcontainers import SortedList
    
class Solution:
    def getResults(self, queries: List[List[int]]) -> List[bool]:
        sl = SortedList()
        n = min(5 * 10 ** 4, len(queries) * 3)
        sl.add(0)
        sl.add(n)
        
        ans = []
        for q in queries:
            if q[0] == 1:
                x = q[1]
                sl.add(x)
        
        bit = BIT(n + 1)
        for x, y in pairwise(sl):
            bit.add(y, y - x)
        
        for q in reversed(queries):
            if q[0] == 1:
                x = q[1]
                index = sl.index(x)
                after = sl[index + 1]
                before = sl[index - 1]
                sl.remove(x)
                bit.add(after, after - before)
            else:
                _, x, sz = q
                index = sl.bisect_right(x)
                before = sl[index - 1]
                ans.append(bit.query(before) >= sz or (x - before) >= sz)
            
        ans.reverse()
        return ans

class Solution:
    def sortItems(self, n: int, m: int, group: List[int], beforeItems: List[List[int]]) -> List[int]:
        
        def topologicalSort(nodes, pred, succ):
            order, no_pred = [], deque(node for node in nodes if not pred[node])
            while no_pred:
                node = no_pred.popleft()
                order.append(node)
                for s in succ[node]:
                    pred[s].discard(node)
                    if not pred[s]:
                        no_pred.append(s)
            return order if len(order) == len(nodes) else []
        
        group_to_items, new_group = defaultdict(set), m
        for item in range(n):
            if group[item] == -1: group[item] = new_group; new_group += 1
            group_to_items[group[item]].add(item)
        
        intra_pred, intra_succ, inter_pred, inter_succ = defaultdict(set), defaultdict(set), defaultdict(set), defaultdict(set)
        for item in range(n):
            for before in beforeItems[item]:
                if group[item] == group[before]:
                    intra_pred[item].add(before)
                    intra_succ[before].add(item)
                else:
                    inter_pred[group[item]].add(group[before])
                    inter_succ[group[before]].add(group[item])
        
        groups_order = topologicalSort(list(group_to_items.keys()), inter_pred, inter_succ)
        if not groups_order: return []
        
        items_order = []
        for grp in groups_order:
            order = topologicalSort(group_to_items[grp], intra_pred, intra_succ)
            if not order: return []
            items_order.extend(order)
        
        return items_order

class Solution:
    def earliestSecondToMarkIndices(self, A: List[int], B: List[int]) -> int:
        firsts = {}
        for i, b in enumerate(B):
            if A[b - 1] and b not in firsts:
                firsts[b] = i
        
        firsts_inv = {i: b for b, i in firsts.items()}

        def possible(bound):
            # Is B[:bound] enough to clear A?
            pq = []
            mark = 0

            for i in range(bound - 1, -1, -1):
                if i in firsts_inv:
                    heappush(pq, A[firsts_inv[i] - 1])
                    
                    if mark:
                        mark -= 1
                    else:
                        mark += 1
                        heappop(pq)
                else:
                    mark += 1

            return sum(A) - sum(pq) + len(A) - len(pq) <= mark

        lo, hi = 0, len(B) + 1
        while lo < hi:
            mi = lo + hi >> 1
            if not possible(mi):
                lo = mi + 1
            else:
                hi = mi
        
        return lo if lo <= len(B) else -1

class Solution:
    def scoreOfStudents(self, s: str, answers: List[int]) -> int:
        
        @cache
        def fn(lo, hi): 
            """Return possible answers of s[lo:hi]."""
            if lo+1 == hi: return {int(s[lo])}
            ans = set()
            for mid in range(lo+1, hi, 2): 
                for x in fn(lo, mid): 
                    for y in fn(mid+1, hi): 
                        if s[mid] == "+" and x + y <= 1000: ans.add(x + y)
                        elif s[mid] == "*" and x * y <= 1000: ans.add(x * y)
            return ans 
                
        target = eval(s)
        cand = fn(0, len(s))
        ans = 0 
        for x in answers: 
            if x == target: ans += 5
            elif x in cand: ans += 2
        return ans

from sortedcontainers import SortedList
class Solution:
    def lengthOfLIS(self, nums: List[int], k: int) -> int:
        ptr, n, monoQ = 0, len(nums), SortedList([-1])
        lens, inv = [0]*(n+1), sorted(range(n), key=lambda i: (nums[i],-i))

        for ind in inv:
            # Remove stale indices
            while nums[inv[ptr]] < nums[ind]-k:
                monoQ.discard(inv[ptr])
                ptr += 1

            # Original LIS MonoQueue operations
            j = monoQ.bisect(ind)
            if j < len(monoQ) and lens[monoQ[j]] == lens[monoQ[j-1]] + 1:
                monoQ.pop(j)
            monoQ.add(ind)
            lens[ind] = lens[monoQ[j-1]]+1

        return max(lens)

from sortedcontainers import SortedList
class Solution:
    def minimumVisitedCells(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        s0 = [SortedList(range(n)) for _ in range(m)]
        s1 = [SortedList(range(m)) for _ in range(n)]
        q = deque([(0, 0, 1)])

        while q:
            i, j, d = q.popleft()
            if (i, j) == (m-1, n-1):
                return d
            for k in list(s0[i].irange(j+1, min(j+1+grid[i][j], n) - 1)):
                q.append((i, k, d+1))
                s0[i].remove(k)
                s1[k].remove(i)
            for k in list(s1[j].irange(i+1, min(i+1+grid[i][j], m) - 1)):
                q.append((k, j, d+1))
                s1[j].remove(k)
                s0[k].remove(j)
        return -1

class Solution:
    def minDistance(self, houses: List[int], k: int) -> int:
        houses.sort()

        @lru_cache(None)
        def dp(left, right, k):
            if k == 1:                                          # <-- 1.
                mid = houses[(left+right) // 2]
                return sum(abs(houses[i] - mid) for i in range(left, right + 1))

            return min(dp(left, i, 1) + dp(i+1, right, k - 1) 
                       for i in range(left, right - k + 2))     # <-- 2.

        return dp(0, len(houses)-1, k)

class LCA:
    def __init__(self, graph, root=0):
        self.graph = graph
        self.ancestors = defaultdict(list)
        self.time_in = dict()
        self.time_out = dict()
        self.timer = 0
        self.depth = dict()
        self.dist = dict()
        self.dfs(root, root, [root])
        
    def dfs(self, v, parent, path, d=0):
        self.timer += 1
        self.time_in[v] = self.timer
        up = 1
        while len(path) >= up:
            self.ancestors[v].append(path[-up])
            up *= 2
        self.depth[v] = len(path)
        self.dist[v] = d
        path.append(v)
        for u, w in self.graph[v].items():
            if u != parent:
                self.dfs(u, v, path, d + w)
        path.pop()
        self.timer += 1
        self.time_out[v] = self.timer

    def is_ancestor(self, u, v):
        return self.time_in[u] <= self.time_in[v] \
               and self.time_out[u] >= self.time_out[v]
            
    def lca(self, u, v):
        if self.is_ancestor(u, v):
            return u
        elif self.is_ancestor(v, u):
            return v
        d = len(self.ancestors[u]) - 1
        while d >= 0:
            d = min(d, len(self.ancestors[u]) - 1)
            if not self.is_ancestor(self.ancestors[u][d], v):
                u = self.ancestors[u][d]
            d -= 1
        return self.ancestors[u][0]

    def distance(self, u, v):
        a = self.lca(u, v)
        if a in {u, v}:
            return abs(self.dist[v] - self.dist[u])
        return (self.dist[u] - self.dist[a]) + (self.dist[v] - self.dist[a])

    def find_node_dist(self, u, distance, mode=0):
        """mode 0: find the first node between root and u with a distance >= distance
           mode 1: find the last node between root and u with a distance <= distance
        """
        d = len(self.ancestors[u]) - 1
        m = u
        while d >= 0:
            d = min(d, len(self.ancestors[u]) - 1)
            v = self.ancestors[u][d]
            if self.dist[v] >= distance:
                m = v
                u = self.ancestors[u][d]
            d -= 1
        if mode == 0 or self.dist[m] == distance:
            return m
        return self.ancestors[m][0]

    def median(self, u, v):
        goal = (self.distance(u, v)) / 2
        a = self.lca(u, v)
        if u == a:
            return self.find_node_dist(v, goal + self.dist[u])
        elif v == a:
            return self.find_node_dist(u, goal + self.dist[v], 1)
        else:
            d = self.distance(a, u)
            if d >= goal:
                return self.find_node_dist(u, d - goal + self.dist[a], 1)
            else:
                return self.find_node_dist(v, goal - d + self.dist[a])
                
class Solution:
    def findMedian(self, n: int, edges: List[List[int]], queries: List[List[int]]) -> List[int]:
        graph = defaultdict(dict)
        for u, v, w in edges:
            graph[u][v] = graph[v][u] = w
        lca = LCA(graph)
        return [lca.median(u, v) for u, v in queries]

class Solution:
    def countPaths(self, grid: List[List[int]]) -> int:
        noOfRows, noOfCols, res = len(grid), len(grid[0]), 0
        dp = [[-1 for _ in range(noOfCols)] for _ in range(noOfRows)]
        
        def dfs(row: int, col: int, prev: int, dp: List[List[int]], grid: List[List[int]]) -> int:
            directions = [[0, 1], [0, -1], [1, 0], [-1, 0]]
            if row < 0 or col < 0 or row >= len(grid) or col >= len(grid[0]) or grid[row][col] <= prev:
                return 0
            if dp[row][col] != -1: 
                return dp[row][col]
            ans = 1
            for direction in directions:
                newRow, newCol = row + direction[0], col + direction[1]
                ans += dfs(newRow, newCol, grid[row][col], dp, grid)
            dp[row][col] = ans
            return ans
        
        for row in range(noOfRows):
            for col in range(noOfCols):
                res += dfs(row, col, -1, dp, grid)
        return res % (10 ** 9 + 7)

class Solution:
    def maxPathLength(self, coordinates: List[List[int]], k: int) -> int:
        def lis(arr):
            # greedy O(n log n) LIS approach
            # We sort by (x, -y), and track only the y coordinate.
            # Because of this sorting, for a given (x,y) if y > lis[-1]
            # then it is necessarily true that x is strictly larger than the previous x-coordinate.
            arr.sort(key=lambda tup: (tup[0], -tup[1]))
            res = []
            for x,y in arr:
                if not res or y > res[-1]:
                    res.append(y)
                else:
                    i = bisect_left(res, y)
                    res[i] = y
            
            return len(res)
        
        mx, my = coordinates[k]
        coordinates.sort()
        
        # smaller elements
        left = [(x,y) for x,y in coordinates if x < mx and y < my]
        
        # larger elements
        right = [(x,y) for x,y in coordinates if x > mx and y > my]

        return 1 + lis(left) + lis(right)

class Trie:
    def __init__(self):
        self.root = {}
    def insert(self, w, reverse=False):
        cur = self.root
        indices = set()
        for c in w:
            if c in cur:
                cur = cur[c]
            else:
                cur[c] = {}
                cur = cur[c]
            if 'end' in cur:
                indices.add(cur['end'])
        cur['end'] = w[::-1] if reverse else w
        return indices

class Solution:
    def countPrefixSuffixPairs(self, words: List[str]) -> int:
        pref = Trie()
        suf = Trie()
        ct = defaultdict(int)
        res = 0
        for w in words:
            indices1 = pref.insert(w)
            rw = w[::-1]
            indices2 = suf.insert(rw, True)
            # len(indices1) and len(indices2) are biunded by len(w)
            for j in indices1:
                if j in indices2:
                    res += ct[j]
            ct[w] += 1
        return res

class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        # Solution 2: Slightly More Efficient
        mod, d = 10**9 + 7, n - 1
        if k > d:       return 0
        r, C = k, 1
        if r > d - r:   r = d - r
        if r:
            inv = [0] * (r + 1)
            inv[1] = 1
            for i in range(2, r + 1):
                inv[i] = mod - (mod // i) * inv[mod % i] % mod
            for i in range(1, r + 1):
                C = C * (d - r + i) % mod * inv[i] % mod
        return m * C % mod * pow(m - 1, d - k, mod) % mod




        # Solution 1: First Solution
        def comb(a, b):
            return fac[a] * inv[b] % mod * inv[a - b] % mod if 0 <= b <= a else 0

        mod = 10**9 + 7
        if k > n - 1:
            return 0

        fac = [1] * n
        for i in range(1, n):
            fac[i] = fac[i - 1] * i % mod

        inv = [1] * n
        inv[n - 1] = pow(fac[n - 1], mod - 2, mod)
        for i in range(n - 1, 0, -1):
            inv[i - 1] = inv[i] * i % mod

        return m * comb(n - 1, k) % mod * pow(m - 1, n - 1 - k, mod) % mod

from typing import List

class Solution:
    def splitArraySameAverage(self, nums: List[int]) -> bool:
        total_sum = sum(nums)
        n = len(nums)
        
        # If there's only one element, we cannot split it into two non-empty subsets
        if n == 1:
            return False
        
        # Helper function to calculate the possible subset sums
        def possible_sums(arr: List[int]) -> int:
            subset_sums = 1
            for a in arr:
                subset_sums |= (subset_sums << a)
            return (subset_sums - 1) ^ (1 << sum(arr))
        
        # Transform nums to the differences from the target average
        transformed_nums = [n * num - total_sum for num in nums]
        
        # If there's a zero in transformed_nums, we can split directly
        if 0 in transformed_nums:
            return True
        
        # Split transformed numbers into positive and negative
        positives = [num for num in transformed_nums if num > 0]
        negatives = [-num for num in transformed_nums if num < 0]
        
        # Check if there's an overlap in achievable sums from positive and negative numbers
        return bool(possible_sums(positives) & possible_sums(negatives))

from sortedcontainers import SortedList

class Solution:
    def findXSum(self, A: List[int], K: int, X: int) -> List[int]:
        bot = SortedList()
        top = SortedList()
        count = Counter()
        cur_sum = 0

        def update(x, qty):
            nonlocal cur_sum

            if count[x]:
                try:
                    bot.remove([count[x], x])
                except:
                    top.remove([count[x], x])
                    cur_sum -= count[x] * x

            count[x] += qty
            if count[x]:
                bot.add([count[x], x])

        ans = []
        for i in range(len(A)):
            update(A[i], 1)
            if i >= K:
                update(A[i - K], -1)

            # rebalance
            while bot and len(top) < X:
                cx, x = bot.pop()
                cur_sum += cx * x
                top.add([cx, x])

            while bot and bot[-1] > top[0]:
                cx, x = bot.pop()
                cy, y = top.pop(0)
                cur_sum += cx * x - cy * y
                bot.add([cy, y])
                top.add([cx, x])

            if i >= K - 1:
                ans.append(cur_sum)

        return ans

class Solution:
    def maximumScore(self, nums: List[int], multipliers: List[int]) -> int:
        n = len(nums)
        m = len(multipliers)
        
        @lru_cache(None)
        #To Save Computed Result
        
        def X(i, left):
            
            if i==m:
                return 0
            
            return max  (   (multipliers[i] * nums[left])          + X(i + 1, left + 1), 
                            (multipliers[i] * nums[n-1-(i-left)])  + X(i + 1, left)       )        
                
        #Start from Zero operations
        return X(0,0)

class Solution:
    def connectTwoGroups(self, cost):
        m, n = len(cost), len(cost[0])

        ans = [min(i) for i in zip(*cost)]

        @lru_cache(None)
        def dfs(i,mask):
            if i == m: return sum(ans[j] for j in range(n) if not (mask & (1<<j)))
            return min(cost[i][j] + dfs(i+1,mask|(1<<j)) for j in range(n))

        return dfs(0,0)

class Solution:
    def waysToReachTarget(self, target: int, types: List[List[int]]) -> int:
        n = len(types)
        dp = [[0]*(1+n) for _ in range(target+1)]
        for j in range(n+1): dp[0][j] = 1
        for i in range(1, target+1): 
            for j in range(n-1, -1, -1): 
                c, m = types[j]
                for x in range(c+1): 
                    if i - x*m >= 0: dp[i][j] += dp[i-x*m][j+1]
                    else: break 
                dp[i][j] %= 1_000_000_007
        return dp[target][0]

import bisect

class Solution:

    def __init__(self):
        self.events = []

    # Cache decorator to memoize results of function calls
    @cache
    def solve(self, i, k):
        if i >= len(self.events): 
            return 0
        if k <= 0: 
            return 0
        
        # Retrieve start time, end time, and value of current event
        s, e, v = self.events[i]
        
        # Find the next event that starts after the current event ends
        j = bisect.bisect(self.events, [e+1])
        
        # We have two options: either take the current event or don't
        return max(v + self.solve(j, k - 1), self.solve(i + 1, k))

    def maxValue(self, events: List[List[int]], k: int) -> int:
        events.sort()  # Sort events based on their start times
        self.events = events
        return self.solve(0, k)

class Solution:
    def minOperations(self, nums: List[int], numsDivide: List[int]) -> int:
        
        gcd_, mn, ans = gcd(*numsDivide), inf, 0

        mn = min(filter(lambda x: gcd_ % x == 0, nums), default = inf)
        if mn == inf: return -1
       
        return sum(num < mn for num in nums)

class Solution:
    def countSubMultisets(self, nums: List[int], l: int, r: int) -> int:
        dp = [1] + [0] * r
        counts = collections.Counter(nums)
        zeros = counts.pop(0, 0) + 1
        for a, c in counts.items():
            stride_sums = dp[:]
            for i in range(a, r + 1):
                stride_sums[i] += stride_sums[i - a]
            for k in range(r, 0, -1):
                dp[k] = stride_sums[k] - stride_sums[k - a * c - a] if k >= a * c + a else stride_sums[k]

        return zeros * sum(dp[l:r+1]) % (10 ** 9 + 7)

N = 100000
is_prime = [True] * (N + 1)
is_prime[0] = is_prime[1] = False
for i in range(2, int(N**0.5) + 1):
    if is_prime[i]:
        for j in range(i * i, N + 1, i):
            is_prime[j] = False

class LazySegmentTree:
    def __init__(self, data, default=0, func=max):
        self._default = default
        self._func = func
        self._len = len(data)
        self._size = 1 << (self._len - 1).bit_length()
        self._lazy = [0] * (2 * self._size)
        self.data = [default] * (2 * self._size)
        self.data[self._size:self._size + self._len] = data
        for i in range(self._size - 1, 0, -1):
            self.data[i] = func(self.data[2 * i], self.data[2 * i + 1])

    def _push(self, idx):
        q = self._lazy[idx]
        if q:
            self._lazy[2 * idx] += q
            self._lazy[2 * idx + 1] += q
            self.data[2 * idx] += q
            self.data[2 * idx + 1] += q
            self._lazy[idx] = 0

    def _update(self, idx):
        for h in range(idx.bit_length() - 1, 0, -1):
            self._push(idx >> h)

    def _build(self, idx):
        while idx > 1:
            idx >>= 1
            self.data[idx] = self._func(self.data[2 * idx], self.data[2 * idx + 1]) + self._lazy[idx]

    def add(self, l, r, v):
        l0, r0 = l + self._size, r + self._size
        l1, r1 = l0, r0
        while l0 < r0:
            if l0 & 1:
                self._lazy[l0] += v
                self.data[l0] += v
                l0 += 1
            if r0 & 1:
                r0 -= 1
                self._lazy[r0] += v
                self.data[r0] += v
            l0 >>= 1
            r0 >>= 1
        self._build(l1)
        self._build(r1 - 1)

    def query(self, l, r):
        l += self._size
        r += self._size
        self._update(l)
        self._update(r - 1)
        res = self._default
        while l < r:
            if l & 1:
                res = self._func(res, self.data[l])
                l += 1
            if r & 1:
                r -= 1
                res = self._func(res, self.data[r])
            l >>= 1
            r >>= 1
        return res

class Solution:
    def maximumCount(self, nums, queries):
        n = len(nums)
        self.nums = [0] * n
        self.pos = defaultdict(lambda: SortedList([-1, n]))
        self.st = LazySegmentTree([0] * (n + 1))
        def update(idx, val):
            old = self.nums[idx]
            if is_prime[old]:
                lst = self.pos[old]
                i = lst.bisect_left(idx)
                prv = lst[i-1]
                nxt = lst[i+1]
                if prv == -1:
                    self.st.add(idx+1, nxt+1, -1)
                if nxt == n:
                    self.st.add(prv+1, idx+1, -1)
                lst.remove(idx)
            self.nums[idx] = val
            if is_prime[val]:
                lst = self.pos[val]
                lst.add(idx)
                i = lst.bisect_left(idx)
                prv = lst[i-1]
                nxt = lst[i+1]
                if prv == -1:
                    self.st.add(idx+1, nxt+1, 1)
                if nxt == n:
                    self.st.add(prv+1, idx+1, 1)
        for i, v in enumerate(nums):
            update(i, v)
        res = []
        for idx, val in queries:
            update(idx, val)
            res.append(self.st.query(1, n))
        return res

class Solution:
    def minTaps(self, n: int, ranges: List[int]) -> int:
        max_range = [0] * (n + 1)
        
        for i in range(len(ranges)):
            left = max(0, i - ranges[i])
            right = min(n, i + ranges[i])
            max_range[left] = max(max_range[left], right)
        
        end = farthest = taps = 0
        i = 0
        
        while end < n:
            while i <= end:
                farthest = max(farthest, max_range[i])
                i += 1
            
            if farthest <= end:
                return -1  # Unable to cover the entire garden
            
            end = farthest
            taps += 1
        
        return taps

class Solution:
    def minDays(self, grid: List[List[int]]) -> int:
        def count_islands():
            seen = set()
            
            def dfs(r, c):
                stack = [(r, c)]
                while stack:
                    x, y = stack.pop()
                    for nx, ny in [(x-1, y), (x+1, y), (x, y-1), (x, y+1)]:
                        if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == 1 and (nx, ny) not in seen:
                            seen.add((nx, ny))
                            stack.append((nx, ny))
            
            islands = 0
            for i in range(len(grid)):
                for j in range(len(grid[0])):
                    if grid[i][j] == 1 and (i, j) not in seen:
                        islands += 1
                        seen.add((i, j))
                        dfs(i, j)
            return islands
        
        if count_islands() != 1:
            return 0
        
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j] == 1:
                    grid[i][j] = 0
                    if count_islands() != 1:
                        return 1
                    grid[i][j] = 1
        
        return 2

class Solution(object):
    def earliestAndLatest(self, n, a, b):
        """
        :type n: int
        :type firstPlayer: int
        :type secondPlayer: int
        :rtype: List[int]
        """
        def simplify(n, a, b):
            # swap
            if a>b: a, b = b, a
            # flip
            if a+b >= n+1:
                a, b = n+1-b, n+1-a
            return n, a, b
    
        def get_info(n,a,b):
            ll, rr = a-1, n-b
            aa = n-ll
            bb = 1+rr
            return ll,rr,aa,bb

        def while_loop(n, a, b):
            ans = 1
            while a+b < n+1:
                n = (n+1)/2
                ans += 1
            if b-a-1==0:
                while n%2:
                    n = (n+1)/2
                    ans += 1
            return ans

        def solve_fast(n, a, b):
            n, a, b = simplify(n, a, b)
            if a+b == n+1: 
                return 1

            # b is on the left, including center
            if b <= (n+1)/2:
                return while_loop(n, a, b)
            
            # b is on the right
            ll, rr, aa, bb = get_info(n, a, b)
            if (ll%2==1 and bb-a-1==0):
                if (n%2==0) and (b == n/2+1):                    
                    return 1 + while_loop((n+1)/2, a, a+1)
                else:
                    return 3
            else:
                return 2

        def solve_slow(n, a, b):
            n, a, b = simplify(n, a, b)
            if a+b==n+1: 
                return 1
            # b is in the left, all can be deleted
            if b <= n+1-b:  
                return 1+solve_slow((n+1)/2, 1, 2)
            else:
                # b is in the right
                ll, rr, aa, bb = get_info(n, a, b)
                keep = (b-bb-1)/2 + n%2
                return 1+solve_slow((n+1)/2, 1, 1+keep+1) 

        return [solve_fast(n,a,b), solve_slow(n,a,b)]

class Solution:
    def movesToChessboard(self, board: List[List[int]]) -> int:
        n = len(board)
        
        def fn(vals): 
            """Return min moves to transform to chessboard."""
            total = odd = 0 
            for i, x in enumerate(vals): 
                if vals[0] == x: 
                    total += 1
                    if i&1: odd += 1
                elif vals[0] ^ x != (1 << n) - 1: return inf
            ans = inf 
            if len(vals) <= 2*total <= len(vals)+1: ans = min(ans, odd)
            if len(vals)-1 <= 2*total <= len(vals): ans = min(ans, total - odd)
            return ans 
        
        rows, cols = [0]*n, [0]*n
        for i in range(n): 
            for j in range(n): 
                if board[i][j]: 
                    rows[i] ^= 1 << j 
                    cols[j] ^= 1 << i
        ans = fn(rows) + fn(cols)
        return ans if ans < inf else -1

class Solution:
    def goodSubtreeSum(self, vals: List[int], par: List[int]) -> int:
        N = len(vals)
        adj = [[] for _ in range(N)]
        for u in range(1, N):
            adj[par[u]].append(u)

        def dfs(u):
            du = {0: 0}
            s = str(abs(vals[u]))
            if len(s) == len(set(s)):
                m = sum(1 << int(c) for c in s)
                du[m] = vals[u]

            for v in adj[u]:
                dv = dfs(v)
                for mv, sv in dv.items():
                    for mu, su in list(du.items()):
                        if mu & mv == 0:
                            du[mu | mv] = max(du.get(mu | mv, 0), su + sv)

            self.ans += max(du.values())
            return du

        self.ans = 0
        dfs(0)
        return self.ans % (10**9 + 7)

class Solution:
    def getMaxFunctionValue(self, receiver: List[int], k: int) -> int:
        m, n = k.bit_length(), len(receiver)
        # pos[i][j] means the end point after move 2^i steps from j
        pos = [[receiver[i] for i in range(n)] for j in range(m)]
        # profit[i][j] means the profit after move 2^i steps from j, not include j itself
        profit = [[receiver[i] for i in range(n)] for j in range(m)]
        for i in range(1, m):
            for j in range(n):
                x = pos[i-1][j]
                pos[i][j] = pos[i-1][x]
                profit[i][j] = profit[i-1][j] + profit[i-1][x]
        def fuck(now, p):
            if p == -1: return 0
            if (k & (1 << p)) == 0: return fuck(now, p - 1)
            return profit[p][now] + fuck(pos[p][now], p - 1)

        return max([fuck(i, m - 1) + i for i in range(n)])

class Solution:
    def minimumScore(self, s: str, t: str) -> int:
        suffix = [-1]*len(s)
        j = len(t)-1
        for i in reversed(range(len(s))): 
            if 0 <= j and s[i] == t[j]: j -= 1
            suffix[i] = j 
        ans = j + 1
        j = 0 
        for i, ch in enumerate(s): 
            ans = min(ans, max(0, suffix[i] - j + 1))
            if j < len(t) and s[i] == t[j]: j += 1
        return min(ans, len(t)-j)

class Solution:
    def distinctEchoSubstrings(self, text: str) -> int:
        text_values = [ord(char) - 97 for char in text]
        hash_map = {}
        powers_of_26 = [1]
        

        for i in range(1, len(text) + 1):
            powers_of_26.append(powers_of_26[i - 1] * 26)
            

        for substring_length in range(1, len(text_values) // 2 + 1):
            current_hash = 0
            for k in range(0, substring_length):
                current_hash = current_hash * 26 + text_values[k]
            hash_map[(0, substring_length)] = current_hash
            
            for start_index in range(1, len(text_values) - substring_length + 1):

                current_hash -= text_values[start_index - 1] * powers_of_26[substring_length - 1]
                current_hash = current_hash * 26 + text_values[start_index + substring_length - 1]
                hash_map[(start_index, start_index + substring_length)] = current_hash

        distinct_substrings = set()
        

        for pair in hash_map:
            first_pair = pair
            second_pair = (pair[1], pair[1] + (first_pair[1] - first_pair[0]))
            if first_pair in hash_map and second_pair in hash_map and hash_map[first_pair] == hash_map[second_pair]:
                distinct_substrings.add((first_pair[1] - first_pair[0], hash_map[first_pair]))
                    
        return len(distinct_substrings)

class Solution:
    def numberOfGoodPaths(self, vals: List[int], edges: List[List[int]]) -> int:

        def get_root(i):
            if i == par[i]: return i
            par[i] = get_root(par[i])
            return par[i]

        def connect(i, j):
            i,j = get_root(i), get_root(j)
           
            if i != j:
                if sz[i] < sz[j]: i, j = j, i
                par[j] = i
                sz[i] += sz[j]
                
                if cur[i] == cur[j]:
                    r = cnt[i] * cnt[j]
                    cnt[i] += cnt[j]
                    return r
                
                elif cur[i] < cur[j]:
                    cur[i],cnt[i] = cur[j],cnt[j]
            return 0
                    
        n = ans =len(vals)
        sz, cur,cnt, par  = [1]*n, vals,[1] *n, list(range(n))
        
        for a, b in sorted(edges, key=lambda p: max(vals[p[0]], vals[p[1]])):
            ans += connect(a, b)
            
        return ans

from collections import deque

class Solution(object):
    def areConnected(self, n, t, queries):
        if t == 0:
            return [True] * len(queries)  # all are connected if threshold is 0

        g = [[] for _ in range(n + 1)]  # adjacency list

        for i in range(t + 1, n + 1):
            j = i * 2
            while j <= n:
                g[i].append(j)
                g[j].append(i)
                j += i

        label = [0] * (n + 1)  # labels for components
        group = 1

        for i in range(1, n + 1):
            if label[i] == 0:  # unvisited node
                q = deque([i])
                label[i] = group
                while q:
                    cur = q.popleft()
                    for nei in g[cur]:
                        if label[nei] == 0:
                            label[nei] = group
                            q.append(nei)
                group += 1

        return [label[a] == label[b] for a, b in queries]  # check component for each query

from functools import lru_cache #This is used in order to avoid TLE by implementing memoization

class Solution:
    def shortestSuperstring(self, words):
        def makeadj(words):
            l = len(words)
            adj = [["" for z in range(l)] for x in range(l)]
            for i in range(l):
                for j in range(l):
                    if i != j:
                        x = words[i]
                        y = words[j]
                        max_overlap = 0
                        for k in range(1, min(len(x), len(y)) + 1):
                            if x[-k:] == y[:k]:
                                max_overlap = k
                        adj[i][j] = y[max_overlap:]  # Only keep the non-overlapping part
            return adj

        @lru_cache(None)
        def sss(bits, cur):
            if bits == (1 << n) - 1: 
                return ""
            res = "a" * 240
            for i in range(n):
                if (bits & (1 << i)) == 0:
                    ans = adj[cur][i] + sss(bits | (1 << i), i)
                    if len(res) > len(ans):
                        res = ans
            return res
        
        ans = "a" * 240 
        n = len(words)
        adj = makeadj(words)
        for i in range(n):
            x = words[i] + sss(1 << i, i)
            if len(x) < len(ans):
                ans = x
        return ans

class Solution:
    def longestAwesome(self, s: str) -> int:
        n = len(s)
        mask = {}
        cur_mask = 0b0000000000
        perfect_is_naaaaaa = 0b0000000000
        mask[cur_mask] = -1
        ans = 1
        for i in range(n):
            num = int(s[i])
            cur_mask ^= 1 << num
            need_mask = perfect_is_naaaaaa ^ cur_mask
            # all
            if need_mask in mask:
                ans = max(ans, i - mask[need_mask])
            # drop 1
            for bit in range(10):
                n_need_max = need_mask ^ (1 << bit)
                if n_need_max in mask:
                    ans = max(ans, i - mask[n_need_max])

            if cur_mask not in mask:
                mask[cur_mask] = i

        return ans

class Solution:
    def longestPath(self, parent: List[int], s: str) -> int:
        t={}
        for i in range(1,len(parent)):
            if parent[i] not in t:
                t[parent[i]]=[i]
            else:
                t[parent[i]].append(i)
            
        self.ans=1
        def fun(i):
            if i not in t:
                return 1
            res = 1
            for j in t[i]:
                length=fun(j)
                if s[i] != s[j]:
                    self.ans = max(self.ans,length+res)
                    res = max(res,length+1)
            return res
        
        fun(0)
        return self.ans

class Solution:
    def numMusicPlaylists(self, n: int, goal: int, k: int) -> int:
        MOD = 10**9 + 7
        dp = [[0 for _ in range(n + 1)] for _ in range(2)]
        dp[0][0] = 1

        for i in range(1, goal + 1):
            dp[i%2][0] = 0
            for j in range(1, min(i, n) + 1):
                dp[i%2][j] = dp[(i - 1)%2][j - 1] * (n - (j - 1)) % MOD
                if j > k:
                    dp[i%2][j] = (dp[i%2][j] + dp[(i - 1)%2][j] * (j - k)) % MOD

        return dp[goal%2][n]

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        count_1 = s.count("1")
        
        @cache
        def is_count_1_valid(num, limit):
            if num == 1:
                return True
            if limit == 0:
                return False
            return is_count_1_valid(bin(num).count("1"), limit - 1)
        
        res = 0 
        MOD = 10 ** 9 + 7
        for i in range(len(s) - 1, -1, -1):
            if s[i] == '1':
                count_1 -= 1
                length = len(s) - i - 1
                for j in range(length + 1):
                    if is_count_1_valid(count_1 + j, k - 1):
                        res += math.comb(length, j)   ## O(n)
                        res = res % MOD
        return res

MOD = 1000000007
MX = 100001

class Solution:
    def __init__(self):
        self.primeFactors = [0] * MX
        self._precompute_prime_factors()

    def _precompute_prime_factors(self):
        for i in range(2, MX):
            if self.primeFactors[i] == 0:
                for j in range(i, MX, i):
                    self.primeFactors[j] += 1

    def maximumScore(self, nums, k):
        n = len(nums)
        left, right = [-1] * n, [n] * n
        stack = []

        for i in range(n):
            while stack and self.primeFactors[nums[stack[-1]]] < self.primeFactors[nums[i]]:
                right[stack.pop()] = i
            if stack:
                left[i] = stack[-1]
            stack.append(i)

        elements = sorted(((nums[i], left[i], right[i], i) for i in range(n)), reverse=True)

        ans = 1
        for v, l, r, i in elements:
            total = (i - l) * (r - i)
            if total >= k:
                ans = (ans * pow(v, k, MOD)) % MOD
                break
            ans = (ans * pow(v, total, MOD)) % MOD
            k -= total

        return ans

class DSU:
    def __init__(self, n):
        self.n = n
        self.p = list(range(n+1))
        self.size = [1]*(n+1)
        self.restrictions = [set() for _ in range(n+1)]
        
    def find(self, u):
        if self.p[u] == u:
            return u
        self.p[u] = self.find(self.p[u])
        return self.p[u]
    
    def add_restriction(self, a, b):
        pa, pb = self.find(a), self.find(b)
        if pa != pb:
            self.restrictions[pa].add(pb)
            self.restrictions[pb].add(pa)
    
    def can_unite(self, a, b):
        pa, pb = self.find(a), self.find(b)
        if pa == pb:
            return True

        return pb not in self.restrictions[pa]
    
    def unite(self, a, b):
        if not self.can_unite(a, b):
            return False
            
        pa, pb = self.find(a), self.find(b)
        if pa != pb:
            if self.size[pa] < self.size[pb]: pa, pb = pb, pa
            
            self.restrictions[pa].update(self.restrictions[pb])
            for other_parent in self.restrictions[pb]:
                self.restrictions[other_parent].remove(pb)
                self.restrictions[other_parent].add(pa)
            
            self.size[pa] += self.size[pb]
            self.p[pb] = pa
        return True


class Solution:
    def friendRequests(self, n: int, restrictions: List[List[int]], requests: List[List[int]]) -> List[bool]:
        dsu = DSU(n)
        
        for u, v in restrictions:
            dsu.add_restriction(u, v)
        
        return [dsu.unite(u, v) for u, v in requests]

class Solution:
    def colorTheGrid(self, m: int, n: int) -> int:
        @cache
        def g(prev):
            def gg(i,cur):
                if i==m: return [cur]
                return sum((gg(i+1,cur+cand) for cand in 'rgb'
                    if prev[i]!=cand and (i==0 or cur[-1]!=cand)),[])

            return gg(0,'')

        @cache
        def f(j,prev):
            if j==n: return 1
            return sum(f(j+1,cur) for cur in g(prev))%(10**9+7)

        return f(0,'_'*m)

from collections import deque, defaultdict

class Solution:
    def largestPathValue(self, colors: str, edges: List[List[int]]) -> int:
        n = len(colors)
        adj = [[] for _ in range(n)]
        indegree = [0] * n

        for u, v in edges:
            adj[u].append(v)
            indegree[v] += 1

        dp = [[0] * 26 for _ in range(n)]
        queue = deque()

        for i in range(n):
            if indegree[i] == 0:
                queue.append(i)
            dp[i][ord(colors[i]) - ord('a')] = 1

        visited = 0
        maxColor = 0

        while queue:
            node = queue.popleft()
            visited += 1

            for neighbor in adj[node]:
                for c in range(26):
                    inc = 1 if ord(colors[neighbor]) - ord('a') == c else 0
                    dp[neighbor][c] = max(dp[neighbor][c], dp[node][c] + inc)

                indegree[neighbor] -= 1
                if indegree[neighbor] == 0:
                    queue.append(neighbor)

            maxColor = max(maxColor, max(dp[node]))

        return maxColor if visited == n else -1

MOD = 10**9 + 7
class Solution:
    def numberOfPermutations(self, n: int, requirements):
        req = {x: y for x, y in requirements}
        if 0 in req and req[0] != 0:
            return 0
        max_c = max(req.values(), default=0)
        dp0 = {0: 1}
        for i in range(1, n):
            dp1 = {}
            for c in dp0:
                for j in range(i + 1):
                    new_c = c + j
                    if new_c > max_c:
                        break
                    if i in req and req[i] != new_c:
                        continue
                    dp1[new_c] = (dp1.get(new_c, 0) + dp0[c]) % MOD
            dp0 = dp1
        target = req.get(n - 1, None)
        if target is None:
            return sum(dp0.values()) % MOD
        return dp0.get(target, 0)

class Solution:
    def maxValue(self, nums: List[int], k: int) -> int:
        n = len(nums)
        
        def get_possible(a):
            t1 = {(0, 0)}
            d = defaultdict(lambda: -1)
            for i, x in enumerate(a):
                t2 = set()
                for taken, val in t1:
                    if taken < k:
                        t2.add((taken + 1, val | x))
                        if taken + 1 == k and val | x not in d:
                            d[val | x] = i + 1
                t1.update(t2)
            return d
        
        a = get_possible(nums)
        b = get_possible(nums[::-1])
        ans = -float('inf')
        
        for v1, x in a.items():
            for v2, y in b.items():
                if x + y <= n:
                    ans = max(ans, v1 ^ v2)
        
        return ans

class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:

        def count(arr: list, res = 0)-> int:                    # <-- 1)

            d = defaultdict(int)
            
            for num in arr:
                tmp = defaultdict(int)
                for and_ in d:
                    tmp[and_ & num]+= d[and_]

                tmp[num]+= 1
                d = tmp
                res+= d[k]

            return res

        
        grps = [list(g) for key,g in groupby(nums,              # <-- 2)
                              lambda x: x &k == k) if key]

        return sum(map(count,grps))                             # <-- 3)

class Solution:
    def minimumWhiteTiles(self, floor: str, numCarpets: int, carpetLen: int) -> int:
        
        @cache
        def fn(i, n):
            """Return min while tiles at k with n carpets left."""
            if n < 0: return inf 
            if i >= len(floor): return 0 
            if floor[i] == '1': return min(fn(i+carpetLen, n-1), 1 + fn(i+1, n))
            return fn(i+1, n)
        
        return fn(0, numCarpets)

class Solution:
    def findAllPeople(self, n: int, meetings: List[List[int]], firstPerson: int) -> List[int]:
        groups = [i for i in range(n)]
        groups[firstPerson] = 0

        meetings.sort(key=lambda x: x[2])

        size = len(meetings)
        i = 0
        while i < size:
            current_time = meetings[i][2]
            temp = []
            while i < size and meetings[i][2] == current_time:
                g1 = self.find(groups, meetings[i][0])
                g2 = self.find(groups, meetings[i][1])
                groups[max(g1, g2)] = min(g1, g2)
                temp.extend([meetings[i][0], meetings[i][1]])
                i += 1
            for j in temp:
                if self.find(groups, j) != 0:
                    groups[j] = j

        result = []
        for j in range(n):
            if self.find(groups, j) == 0:
                result.append(j)

        return result

    def find(self, groups: List[int], index: int) -> int:
        while index != groups[index]:
            index = groups[index]
        return index

from collections import deque

class Solution:
    def isEscapePossible(self, blocked, source, target):
        BLOCKED = set(map(tuple, blocked))
        MAX = len(blocked) * len(blocked)

        def bfs(start, end):
            visited = set()
            queue = deque([tuple(start)])
            visited.add(tuple(start))
            count = 0

            while queue:
                x, y = queue.popleft()
                if [x, y] == end:
                    return True
                if count > MAX:
                    return True

                for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < 10**6 and 0 <= ny < 10**6 and (nx, ny) not in visited and (nx, ny) not in BLOCKED:
                        visited.add((nx, ny))
                        queue.append((nx, ny))
                count += 1

            return False

        return bfs(source, target) and bfs(target, source)

class Solution:
    def smallestBeautifulString(self, s: str, k: int) -> str:
        s = list(s)
        i = len(s) - 1
        s[i] = chr(ord(s[i]) + 1)
        while 0 <= i < len(s):
            if ord(s[i]) - ord('a') >= k:
                s[i] = 'a'
                i -= 1
                s[i] = chr(ord(s[i]) + 1)
            elif (i >= 1 and s[i] == s[i - 1]) or (i >= 2 and s[i] == s[i - 2]):
                s[i] = chr(ord(s[i]) + 1)
            else:
                i += 1
        return '' if i < 0 else ''.join(s)

from collections import deque

class Solution:
    def minFlips(self, mat: list[list[int]]) -> int:
        m, n = len(mat), len(mat[0])
        #Convert matrix to bitmask
        start = 0
        for i in range(m):
            for j in range(n):
                if mat[i][j] == 1:
                    start |= 1 << (i * n + j)
        flipMasks = []
        for i in range(m):
            for j in range(n):
                mask = 0
                for di, dj in [(0,0),(1,0),(-1,0),(0,1),(0,-1)]:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < m and 0 <= nj < n:
                        mask |= 1 << (ni * n + nj)
                flipMasks.append(mask)
        #bfs
        visited = [False] * (1 << (m * n))
        queue = deque([(start, 0)])
        visited[start] = True
        while queue:
            state, steps = queue.popleft()
            if state == 0:
                return steps
            for mask in flipMasks:
                nxt = state ^ mask
                if not visited[nxt]:
                    visited[nxt] = True
                    queue.append((nxt, steps + 1))
        return -1

class Solution:
    def countPalindromicSubsequences(self, s: str) -> int:

        @lru_cache(None)
        def dp(left: int, rght: int, res = 0):

            for ch in 'abcd':

                l, r = s.find(ch,left,rght), s.rfind(ch,left,rght)
                
                res+= 0 if l==-1 else 1 if l==r else dp(l+1,r)+2

            return res %1_000_000_007

        return dp(0,len(s))

class Solution:
    def pathsWithMaxScore(self, board: List[str]) -> List[int]:
        grid = []
        self.dp = {}
        for i in range(len(board)) :
            row = list(board[i])
            for k in range(len(row)) :
                row[k] = -1 if row[k] == 'X' else int(row[k]) if row[k] >= '1' and row[k] <= '9' else 0
            grid.append(row)
        
        def dfsUtil(i, j) :
            if i >= len(grid) or j >= len(grid[0]) or grid[i][j] == -1 :
                return (float(-inf), float(-inf))

            if i == len(grid)-1 and j == len(grid)-1 :
                return (0, 1)

            if (i, j) in self.dp :
                return self.dp[(i, j)]

            down = dfsUtil(i+1, j)
            right = dfsUtil(i, j+1)
            diagonal = dfsUtil(i+1, j+1)

            max_sum = max(down[0], max(right[0], diagonal[0]))
            total_paths = 0

            total_paths += down[-1] if down[0] == max_sum else 0
            total_paths += right[-1] if right[0] == max_sum else 0
            total_paths += diagonal[-1] if diagonal[0] == max_sum else 0

            self.dp[(i, j)] = [max_sum+grid[i][j], total_paths]
            return [max_sum+grid[i][j], total_paths] 

        max_sum, paths = dfsUtil(0, 0)
        return [max_sum % ((10 ** 9) + 7), paths % ((10 ** 9) + 7)] if max_sum != float(-inf) else (0, 0)

class Solution:
    def appealSum(self, s: str) -> int:
        res, cur, prev = 0, 0, defaultdict(lambda: -1)
        for i, ch in enumerate(s):
            cur += i - prev[ch]
            prev[ch] = i
            res += cur
        return res

class Solution:
    def minInsertions(self, s: str) -> int:

        n = len(s)

        #This can be solved using longest common subsequence and longest palindromic subsequence
        s1 = s
        s2 = s[::-1]

        #start from last index
        @cache
        def evaluate(index1, index2):
            if(index1 < 0 or index2 < 0):
                return 0
            
            if(s1[index1] == s2[index2]):
                return 1 + evaluate(index1 - 1, index2 - 1)
            else:
                #move index1 and move index2 separately
                return max(evaluate(index1-1,index2), evaluate(index1, index2 - 1))
        
        return n - evaluate(len(s1)-1, len(s2) - 1)

class Solution:
    def findMaximumLength(self, nums):
        N = len(nums)
        pre = [0]
        pre.extend(nums)
        for i in range(1, N + 1):
            pre[i] += pre[i - 1]

        dp = defaultdict(lambda: (0, 0))
        dp[0] = (0, 0)

        for i in range(1, N + 1):
            length, x = dp[i - 1]
            x *= -1

            if x <= nums[i - 1]:
                dp[i] = max(dp[i], (length + 1, -1 * nums[i - 1]))
            else:
                dp[i] = max(dp[i], (length, -1 * (x + nums[i - 1])))

            lb_need = pre[i] - nums[i - 1] + x
            id = next((idx for idx, val in enumerate(pre) if val >= lb_need), N + 1)
            if id <= N:
                dp[id] = max(dp[id], (length + 1, -1 * (x + pre[id] - lb_need)))

        return dp[N][0]

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        binary_arr = []
        for char in s:
            binary_arr.append(int(char))
        group_arr = []
        for binary_num, itr in groupby(binary_arr):
            group_size = len(list(itr))
            group_arr.append(group_size)

        def operationsCount(length):
            if length == 1:
                ops_for_odd_position_1s = sum([int(val == ind % 2) for ind, val in enumerate(binary_arr)])
                ops_for_even_position_1s = sum([int(val != ind % 2) for ind, val in enumerate(binary_arr)])
                return min(ops_for_odd_position_1s, ops_for_even_position_1s)
            return sum([ group_size // (length + 1) for group_size in group_arr])

        l = 1
        r = len(s)
        res = -1
        while l <= r:
            mid = (l + r) // 2
            if operationsCount(mid) > numOps:
                l = mid + 1
            else:
                r = mid - 1
                res = mid
        return res

class Solution:
    def maxChunksToSorted(self, arr: List[int]) -> int:

        acc = zip(accumulate(arr), accumulate(sorted(arr)))

        return len(tuple(filter(lambda x: x[0] == x[1],acc)))

class Solution:
    def minimumTime(self, nums1: List[int], nums2: List[int], x: int) -> int:
        n = len(nums1)
        ind = list(range(n))
        s, d = 0, 0
        for i in range(n):
            s += nums1[i]
            d += nums2[i]
        if s <= x:
            return 0

        # Custom comparator for sorting ind based on nums2 values
        ind.sort(key=lambda i: nums2[i])

        dp = [0] * (n + 1)
        r = n + 1
        for i in range(1, n + 1):
            for j in range(min(i, r - 1), 0, -1):
                dp[j] = max(dp[j], dp[j - 1] + nums2[ind[i - 1]] * j + nums1[ind[i - 1]])
                if s + j * d - dp[j] <= x:
                    r = j
        return r if r <= n else -1

class Solution:
    def countPairs(self, n: int, edges: List[List[int]], queries: List[int]) -> List[int]:
        degree = [0]*n
        freq = defaultdict(int)
        for u, v in edges: 
            degree[u-1] += 1
            degree[v-1] += 1
            freq[min(u-1, v-1), max(u-1, v-1)] += 1
        
        vals = sorted(degree)
        
        ans = []
        for query in queries: 
            cnt = 0 
            lo, hi = 0, n-1
            while lo < hi: 
                if query < vals[lo] + vals[hi]: 
                    cnt += hi - lo # (lo, hi), (lo+1, hi), ..., (hi-1, hi) all valid
                    hi -= 1
                else: lo += 1
            for u, v in freq: 
                if degree[u] + degree[v] - freq[u, v] <= query < degree[u] + degree[v]: cnt -= 1
            ans.append(cnt)
        return ans

class Solution:
    def kthSmallestProduct(self, nums1: List[int], nums2: List[int], k: int) -> int:
        nums1.sort()
        nums2.sort()

        def count_pairs(x: int) -> int:
            count = 0
            for a in nums1:
                if a > 0:
                    # a * b <= x => b <= x // a
                    count += bisect.bisect_right(nums2, x // a)
                elif a < 0:
                    # a * b <= x => b >= ceil(x / a)
                    # careful with negatives
                    target = x // a
                    if x % a != 0:
                        target += 1
                    count += len(nums2) - bisect.bisect_left(nums2, target)
                else:
                    if x >= 0:
                        count += len(nums2)  # zero * anything <= x
                    # else, 0 * any b > negative => contributes nothing
            return count

        # Define search bounds
        low = -10**10
        high = 10**10

        while low < high:
            mid = (low + high) // 2
            if count_pairs(mid) < k:
                low = mid + 1
            else:
                high = mid

        return low

class Solution:
    def minimumChanges(self, st: str, k: int) -> int:
        def num(st):
            n = len(st)
            ans = float('inf')
            for it in fac[len(st)]:
                nu = n // it
                cur = 0
                for i in range(nu // 2):
                    i2 = nu - i - 1
                    for j in range(it):
                        if st[i * it + j] != st[i2 * it + j]:
                            cur += 1
                ans = min(ans, cur)
            return ans

        n = len(st)
        for i in range(2, n + 1):
            fac[i] = []
            for j in range(1, i):
                if i % j == 0:
                    fac[i].append(j)

        dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
        dp[0][0] = 0

        for i in range(n):
            for j in range(i + 1):
                cur = st[j:i + 1]
                add = num(cur)
                for l in range(k):
                    dp[i + 1][l + 1] = min(dp[i + 1][l + 1], dp[j][l] + add)

        return dp[n][k]

