class Solution:
    def leastOpsExpressTarget(self, x: int, target: int) -> int:
        def dfs(target):
            # base1
            if x == target:
                return 0

            # base2
            if x > target:
                return min(2 * target - 1, 2 * (x - target))

            # seen before
            if target in memo:
                return memo[target]

            # otherwise compute  memo[target]

            # run greedily to reach target from x
            prod = x
            count = 0
            while prod < target:
                prod *= x
                count += 1

            # case1; compute lower_power
            lower_power = count + dfs(target - prod // x)

            # case2; compute higher_power
            higher_power = float('inf')
            if prod < 2 * target:
                higher_power = count + 1 + dfs(prod - target)

            # compare
            memo[target] = min(lower_power, higher_power)

            return memo[target]

        # memo[t] := least number of operators s.t. the expression equals the given t
        memo = dict()

        # run dfs
        return dfs(target)

class Trie: 
    def __init__(self): 
        self.root = {}
        
    def insert(self, val): 
        node = self.root 
        for i in reversed(range(15)):
            bit = (val >> i) & 1
            if bit not in node: node[bit] = {"cnt": 0}
            node = node[bit]
            node["cnt"] += 1
        
    def count(self, val, high): 
        ans = 0 
        node = self.root
        for i in reversed(range(15)):
            if not node: break 
            bit = (val >> i) & 1 
            cmp = (high >> i) & 1
            if cmp: 
                if node.get(bit, {}): ans += node[bit]["cnt"]
                node = node.get(1^bit, {})
            else: node = node.get(bit, {})
        return ans 
            
        
class Solution:
    def countPairs(self, nums: List[int], low: int, high: int) -> int:
        trie = Trie()
        ans = 0
        for x in nums: 
            ans += trie.count(x, high+1) - trie.count(x, low)
            trie.insert(x)
        return ans

class Solution:
    def constructGridLayout(self, N: int, edges: List[List[int]]) -> List[List[int]]:
        adj = [[] for _ in range(N)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        deg = [len(row) for row in adj]
        root = deg.index(min(deg))
        path = [root]
        seen = [0] * N
        seen[root] = 1
        for node in path:
            if len(path) >= 2 and deg[path[-1]] == deg[root]:
                break
            adj[node].sort(key=deg.__getitem__)
            for nei in adj[node]:
                if not seen[nei] and deg[nei] <= deg[root] + 1:
                    path.append(nei)
                    seen[nei] = 1
                    break

        C = len(path)
        R = N // C
        ans = [[0] * C for _ in range(R)]
        ans[0] = path
        for r in range(1, R):
            for c in range(C):
                for nei in adj[ans[r - 1][c]]:
                    if not seen[nei]:
                        ans[r][c] = nei
                        seen[nei] = 1
                        break

        return ans

from functools import lru_cache

class Solution:
    def countRoutes(self, locations: list[int], start: int, finish: int, fuel: int) -> int:
        n = len(locations)
        @lru_cache(None)
        def dp(city, rem):
            res = 1 if city == finish else 0
            for nxt in range(n):
                if nxt != city:
                    cost = abs(locations[city] - locations[nxt])
                    if cost <= rem:
                        res = (res + dp(nxt, rem - cost)) % (10**9+7)
            return res

        return dp(start, fuel)

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        # KMP
        # Time Complexity: O(n + m)
        # Space Complexity: O(n + m)
        def lps(s):
            n = len(s)
            lps = [0] * n
            j = 0
            for i in range(1, n):
                while j and s[i] != s[j]:
                    j = lps[j-1]
                if s[i] == s[j]:
                    j += 1
                    lps[i] = j
            return lps
        a, b, c = p.split('*')
        na, nb, nc = len(a), len(b), len(c)
        lps_a, lps_b, lps_c = lps(a + '$' + s)[na+1:], lps(b + '$' + s)[nb+1:], lps(c + '$' + s)[nc+1:]
        ans = inf
        i = j = k = 0
        try:
            while i + nb + nc < len(lps_a):
                while lps_a[i] != na:
                    i += 1
                while j < i + nb or lps_b[j] != nb:
                    j += 1
                while k < j + nc or lps_c[k] != nc:
                    k += 1
                ans = min(ans, k - i + na)
                i += 1
        except:
            pass
        return -1 if ans is inf else ans

class Solution:
    def concatenatedDivisibility(self, nums: List[int], k: int) -> List[int]:
        nums.sort()
        nums = list(map(str, nums))
        res = []
        
        def backtrack(start):
            nonlocal res

            if start == len(nums):
                print(''.join(nums))
                if int(''.join(nums)) % k == 0:
                    print(nums)
                    res = list(map(int, nums))
                return
            
            for i in range(start, len(nums)):
                nums[start], nums[i] = nums[i], nums[start]
                backtrack(start + 1)
                if res: break
                nums[start], nums[i] = nums[i], nums[start]

        backtrack(0)
        return res

class Solution:
    def kthCharacter(self, k: int, operations: List[int]) -> str:
        n, i = 1, 0
        while n < k:
            n *= 2
            i += 1
        d = 0
        while n > 1:
            if k > n // 2:
                k -= n // 2
                d += operations[i - 1]
            n //= 2
            i -= 1
        return chr(d % 26 + ord("a"))

class Solution:
    def shortestSubarray(self, nums: List[int], k: int) -> int:
        res = float("inf")

        cur_sum = 0
        q = deque()  # (prefix_sum, end_idx)

        for r in range(len(nums)):
            cur_sum += nums[r]
            if cur_sum >= k:
                res = min(res, r + 1)

            # Find the minimum valid window ending at r
            while q and cur_sum - q[0][0] >= k:
                prefix, end_idx = q.popleft()
                res = min(res, r - end_idx)

            # Validate the monotonic deque
            while q and q[-1][0] > cur_sum:
                q.pop()
            q.append((cur_sum, r))

        return -1 if res == float("inf") else res

class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        nums = [0]+nums+[float('inf')]
        n = len(nums)
        for i in range(n-1):
            if nums[i] >= nums[i+1]:
                break
        else:
            return (n-2)*(n-1)//2
        for j in range(n-1, 0, -1):
            if nums[j-1] >= nums[j]:
                break
        l = 0
        r = j
        res = 0
        while l <= i:
            while r < n and nums[l] >= nums[r]:
                r += 1
            res += n - r
            l += 1
        return res

class Solution:
    def isNumber(self, s: str) -> bool:
		#Example:               +-     1 or 1. or 1.2 or .2   e or E +- 1     
        engine = re.compile(r"^[+-]?((\d+\.?\d*)|(\d*\.?\d+))([eE][+-]?\d+)?$")
        return engine.match(s.strip(" ")) # i prefer this over putting more things (\S*) in regex

class Solution:
    def getPermutation(self, n: int, k: int) -> str:
        nums = [i for i in range(1, n+1)] # list of numbers from 1 to n
        factorial = [1] * n
        for i in range(1, n):
            factorial[i] = factorial[i-1] * i
        
        k -= 1
        result = []
        for i in range(n-1, -1, -1):
            index = k // factorial[i]
            result.append(str(nums[index]))
            nums.pop(index)
            k = k % factorial[i]
        
        return ''.join(result)

class Solution:
    def totalNQueens(self, n: int) -> int:
        def dfs(queens, dif, sum):
            p = len(queens)
            if p == n:
                self.result += 1
                return None
            for q in range(n):
                if q not in queens and p-q not in dif and p+q not in sum:
                    dfs(queens+[q], dif+[p-q], sum+[p+q])
        
        self.result = 0
        dfs([],[],[])
        return self.result

class Solution:
    def firstMissingPositive(self, nums: List[int]) -> int:
        # Function to swap elements in the array
        def swap(arr, i, j):
            arr[i], arr[j] = arr[j], arr[i]
        
        n = len(nums)
        
        # Place each positive integer i at index i-1 if possible
        for i in range(n):
            while 0 < nums[i] <= n and nums[i] != nums[nums[i] - 1]:
                swap(nums, i, nums[i] - 1)
        
        # Find the first missing positive integer
        for i in range(n):
            if nums[i] != i + 1:
                return i + 1
        
        # If all positive integers from 1 to n are present, return n + 1
        return n + 1

class Solution:
    def solveSudoku(self, board: List[List[str]]) -> None:
        n = 9
        
        
        def isValid(row, col, ch):
            row, col = int(row), int(col)
            
            for i in range(9):
                
                if board[i][col] == ch:
                    return False
                if board[row][i] == ch:
                    return False
                
                if board[3*(row//3) + i//3][3*(col//3) + i%3] == ch:
                    return False
            
            return True
            
        def solve(row, col):
            if row == n:
                return True
            if col == n:
                return solve(row+1, 0)
            
            if board[row][col] == ".":
                for i in range(1, 10):
                    if isValid(row, col, str(i)):
                        board[row][col] = str(i)
                        
                        if solve(row, col + 1):
                            return True
                        else:
                            board[row][col] = "."
                return False
            else:
                return solve(row, col + 1)
            
            
        
        solve(0, 0)
		
